/**
 * Verification Webhook Handler
 * 
 * Handles incoming webhooks from external identity verification services.
 * This is a placeholder implementation that can be adapted for various providers
 * like Smile ID, Onfido, Jumio, etc.
 * 
 * SECURITY: Includes signature verification and idempotency handling.
 */

import { db } from "../db";
import { companyApplications, identityVerifications } from "@shared/schema";
import { eq, and } from "drizzle-orm";
import * as verificationService from "./verificationService";
import { storage } from "../storage";
import type { IncomingHttpHeaders } from "http";
import crypto from "crypto";

// In-memory set for idempotency (in production, use Redis or database)
const processedWebhooks = new Set<string>();
const PROCESSED_WEBHOOK_TTL = 24 * 60 * 60 * 1000; // 24 hours

interface WebhookResult {
  success: boolean;
  error?: string;
  userId?: string;
  alreadyProcessed?: boolean;
}

interface VerificationWebhookPayload {
  event: string;
  eventId?: string;
  data: {
    sessionId: string;
    userId?: string;
    status: "approved" | "declined" | "pending" | "error";
    result?: {
      selfieUrl?: string;
      livenessScore?: number;
      documentVerified?: boolean;
      notes?: string;
    };
    provider?: string;
    timestamp?: string;
  };
}

function verifyWebhookSignature(
  payload: string,
  signature: string | undefined,
  secret: string
): boolean {
  if (!signature) {
    return false;
  }

  // Support multiple signature formats (HMAC-SHA256 is common)
  const expectedSignature = crypto
    .createHmac("sha256", secret)
    .update(payload)
    .digest("hex");

  // Constant-time comparison to prevent timing attacks
  try {
    return crypto.timingSafeEqual(
      Buffer.from(signature),
      Buffer.from(expectedSignature)
    );
  } catch {
    // Buffer length mismatch - signatures don't match
    return false;
  }
}

function getIdempotencyKey(payload: VerificationWebhookPayload): string {
  // Use eventId if available, otherwise combine event + sessionId + timestamp
  if (payload.eventId) {
    return payload.eventId;
  }
  return `${payload.event}:${payload.data.sessionId}:${payload.data.timestamp || Date.now()}`;
}

function isWebhookAlreadyProcessed(idempotencyKey: string): boolean {
  return processedWebhooks.has(idempotencyKey);
}

function markWebhookProcessed(idempotencyKey: string): void {
  processedWebhooks.add(idempotencyKey);

  // Clean up old entries after TTL (simple implementation)
  setTimeout(() => {
    processedWebhooks.delete(idempotencyKey);
  }, PROCESSED_WEBHOOK_TTL);
}

export async function processVerificationWebhook(
  payload: string,
  headers: IncomingHttpHeaders
): Promise<WebhookResult> {
  // Get webhook secret from environment
  const webhookSecret = process.env.VERIFICATION_WEBHOOK_SECRET;

  // SECURITY: Verify webhook signature if secret is configured
  if (webhookSecret) {
    const signature = 
      headers["x-verification-signature"] || 
      headers["x-webhook-signature"] ||
      headers["x-signature"];

    const signatureStr = Array.isArray(signature) ? signature[0] : signature;

    if (!verifyWebhookSignature(payload, signatureStr, webhookSecret)) {
      console.error("[Verification Webhook] Invalid signature - rejecting webhook");
      return { success: false, error: "Invalid webhook signature" };
    }
    console.log("[Verification Webhook] Signature verified successfully");
  } else {
    console.warn("[Verification Webhook] No VERIFICATION_WEBHOOK_SECRET configured - skipping signature verification (NOT RECOMMENDED FOR PRODUCTION)");
  }

  try {
    const data: VerificationWebhookPayload = JSON.parse(payload);

    // Idempotency check - prevent duplicate processing
    const idempotencyKey = getIdempotencyKey(data);
    if (isWebhookAlreadyProcessed(idempotencyKey)) {
      console.log(`[Verification Webhook] Duplicate webhook detected, skipping: ${idempotencyKey}`);
      return { success: true, alreadyProcessed: true };
    }

    console.log(`[Verification Webhook] Processing event: ${data.event} (key: ${idempotencyKey})`);

    let result: WebhookResult;

    switch (data.event) {
      case "verification.completed":
      case "verification.approved":
        result = await handleVerificationApproved(data.data);
        break;

      case "verification.declined":
      case "verification.failed":
        result = await handleVerificationDeclined(data.data);
        break;

      case "verification.pending":
        result = await handleVerificationPending(data.data);
        break;

      default:
        console.log(`[Verification Webhook] Unhandled event type: ${data.event}`);
        result = { success: true };
    }

    // Mark as processed only on success
    if (result.success) {
      markWebhookProcessed(idempotencyKey);
    }

    return result;
  } catch (error: any) {
    console.error("[Verification Webhook] Parse error:", error.message);
    return { success: false, error: "Invalid payload" };
  }
}

async function handleVerificationApproved(
  data: VerificationWebhookPayload["data"]
): Promise<WebhookResult> {
  try {
    const verification = await verificationService.getVerificationByExternalSession(data.sessionId);

    if (!verification) {
      console.error(`[Verification Webhook] No verification found for session: ${data.sessionId}`);
      return { success: false, error: "Verification session not found" };
    }

    // Check if already verified (additional idempotency at data level)
    if (verification.status === "verified") {
      console.log(`[Verification Webhook] User ${verification.founderUserId} already verified, skipping`);
      return { success: true, userId: verification.founderUserId, alreadyProcessed: true };
    }

    const userId = verification.founderUserId;

    await verificationService.markUserVerified(userId, {
      method: "external",
      externalProvider: data.provider,
      externalSessionId: data.sessionId,
      selfieUrl: data.result?.selfieUrl,
      livenessScore: data.result?.livenessScore,
      notes: data.result?.notes || "Verified via external provider",
    });

    await updatePendingApplications(userId);

    await storage.createAuditLog({
      actorUserId: userId,
      action: "identity_verified",
      entityType: "identity_verification",
      entityId: verification.id.toString(),
      details: {
        method: "external",
        provider: data.provider,
        sessionId: data.sessionId,
      },
    });

    console.log(`[Verification Webhook] User ${userId} verified successfully`);
    return { success: true, userId };
  } catch (error: any) {
    console.error("[Verification Webhook] Error handling approval:", error.message);
    return { success: false, error: error.message };
  }
}

async function handleVerificationDeclined(
  data: VerificationWebhookPayload["data"]
): Promise<WebhookResult> {
  try {
    const verification = await verificationService.getVerificationByExternalSession(data.sessionId);

    if (!verification) {
      return { success: false, error: "Verification session not found" };
    }

    // Check if already processed
    if (verification.status === "rejected") {
      console.log(`[Verification Webhook] Verification ${verification.id} already rejected, skipping`);
      return { success: true, userId: verification.founderUserId, alreadyProcessed: true };
    }

    await db
      .update(identityVerifications)
      .set({
        status: "rejected",
        notes: data.result?.notes || "Verification declined by provider",
        updatedAt: new Date(),
      })
      .where(eq(identityVerifications.id, verification.id));

    await storage.createAuditLog({
      actorUserId: verification.founderUserId,
      action: "identity_verification_failed",
      entityType: "identity_verification",
      entityId: verification.id.toString(),
      details: {
        reason: data.result?.notes,
        provider: data.provider,
      },
    });

    console.log(`[Verification Webhook] Verification declined for user ${verification.founderUserId}`);
    return { success: true, userId: verification.founderUserId };
  } catch (error: any) {
    console.error("[Verification Webhook] Error handling decline:", error.message);
    return { success: false, error: error.message };
  }
}

async function handleVerificationPending(
  data: VerificationWebhookPayload["data"]
): Promise<WebhookResult> {
  console.log(`[Verification Webhook] Verification still pending for session: ${data.sessionId}`);
  return { success: true };
}

async function updatePendingApplications(userId: string): Promise<void> {
  const pendingApps = await db
    .select()
    .from(companyApplications)
    .where(
      and(
        eq(companyApplications.founderUserId, userId),
        eq(companyApplications.status, "pending_verification")
      )
    );

  for (const app of pendingApps) {
    // Additional idempotency: check if already submitted
    if (app.status !== "pending_verification") {
      console.log(`[Verification Webhook] Application ${app.id} already processed, skipping`);
      continue;
    }

    await db
      .update(companyApplications)
      .set({
        status: "submitted",
        submittedAt: new Date(),
        updatedAt: new Date(),
      })
      .where(
        and(
          eq(companyApplications.id, app.id),
          eq(companyApplications.status, "pending_verification") // Ensure we only update if still pending
        )
      );

    await storage.createAuditLog({
      actorUserId: userId,
      action: "application_auto_submitted",
      entityType: "company_application",
      entityId: app.id.toString(),
      details: {
        previousStatus: "pending_verification",
        newStatus: "submitted",
        reason: "User identity verified",
      },
    });

    console.log(`[Verification Webhook] Application ${app.id} auto-submitted after verification`);
  }
}

server/config/priceBook.ts.content:
/**
 * PriceBook Module
 * 
 * Maps Celion One services to Paystack (NGN) pricing.
 * All payments are processed through Paystack in Nigerian Naira.
 * International customers pay in NGN and their bank handles conversion.
 * 
 * Service Types:
 * - verification: Identity & Compliance Verification (one-off)
 * - incorporation: Company Incorporation Service (one-off)
 * - registered_office: Registered Office Address (yearly subscription)
 *   - Tiers: office_only, office_plus_mail
 */

export type ServiceType = 'verification' | 'incorporation' | 'registered_office';
export type RegisteredOfficeTier = 'office_only' | 'office_plus_mail';
export type PaymentProvider = 'paystack';
export type Currency = 'NGN';

export interface PriceEntry {
  serviceType: ServiceType;
  tier?: RegisteredOfficeTier;
  provider: PaymentProvider;
  currency: Currency;
  amount: number;
  amountDisplay: string;
  isRecurring: boolean;
  recurringInterval?: 'year' | 'month';
  description: string;
}

const PRICE_BOOK: PriceEntry[] = [
  {
    serviceType: 'verification',
    provider: 'paystack',
    currency: 'NGN',
    amount: 2500000, // ₦25,000 in kobo
    amountDisplay: '₦25,000',
    isRecurring: false,
    description: 'Identity & Compliance Verification',
  },
  {
    serviceType: 'incorporation',
    provider: 'paystack',
    currency: 'NGN',
    amount: 10000000, // ₦100,000 in kobo
    amountDisplay: '₦100,000',
    isRecurring: false,
    description: 'Company Incorporation Service',
  },
  {
    serviceType: 'registered_office',
    tier: 'office_only',
    provider: 'paystack',
    currency: 'NGN',
    amount: 14000000, // ₦140,000 in kobo
    amountDisplay: '₦140,000/year',
    isRecurring: true,
    recurringInterval: 'year',
    description: 'Registered Office Address (Office Only)',
  },
  {
    serviceType: 'registered_office',
    tier: 'office_plus_mail',
    provider: 'paystack',
    currency: 'NGN',
    amount: 28000000, // ₦280,000 in kobo
    amountDisplay: '₦280,000/year',
    isRecurring: true,
    recurringInterval: 'year',
    description: 'Registered Office Address (Office + Mail Handling)',
  },
];

export function getPrice(
  serviceType: ServiceType,
  provider: PaymentProvider = 'paystack',
  tier?: RegisteredOfficeTier
): PriceEntry | undefined {
  return PRICE_BOOK.find(p => 
    p.serviceType === serviceType && 
    p.provider === provider &&
    (tier ? p.tier === tier : true)
  );
}

export function getPaystackPrice(
  serviceType: ServiceType,
  tier?: RegisteredOfficeTier
): PriceEntry | undefined {
  return getPrice(serviceType, 'paystack', tier);
}

export function getPricesByProvider(provider: PaymentProvider = 'paystack'): PriceEntry[] {
  return PRICE_BOOK.filter(p => p.provider === provider);
}

export function getPricesByServiceType(serviceType: ServiceType): PriceEntry[] {
  return PRICE_BOOK.filter(p => p.serviceType === serviceType);
}

export function calculateTotal(
  items: { serviceType: ServiceType; tier?: RegisteredOfficeTier }[],
  provider: PaymentProvider = 'paystack'
): { total: number; currency: Currency } {
  let total = 0;
  for (const item of items) {
    const price = getPrice(item.serviceType, provider, item.tier);
    if (price) {
      total += price.amount;
    }
  }
  return { total, currency: 'NGN' };
}

export function validateItems(
  items: { serviceType: ServiceType; tier?: RegisteredOfficeTier }[],
  provider: PaymentProvider = 'paystack'
): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  for (const item of items) {
    const price = getPrice(item.serviceType, provider, item.tier);
    if (!price) {
      if (item.tier) {
        errors.push(`No price found for ${item.serviceType} (${item.tier})`);
      } else {
        errors.push(`No price found for ${item.serviceType}`);
      }
    }
  }
  return { valid: errors.length === 0, errors };
}

export default {
  getPrice,
  getPaystackPrice,
  getPricesByProvider,
  getPricesByServiceType,
  calculateTotal,
  validateItems,
};

server/services/paymentStateService.ts.content:
import { db } from "../db";
import { eq } from "drizzle-orm";
import { 
  payments, 
  companyApplications,
  payoutLedger,
  type Payment
} from "@shared/schema";

export type PaymentState = 
  | "unpaid" 
  | "paid_escrowed" 
  | "released_to_lawyer" 
  | "refunded_partial"
  | "refunded_full"
  | "chargeback";

export interface PaymentStateTransition {
  from: PaymentState;
  to: PaymentState;
  validRoles: ("admin" | "system")[];
  requiresReason: boolean;
}

const VALID_TRANSITIONS: PaymentStateTransition[] = [
  { from: "unpaid", to: "paid_escrowed", validRoles: ["system"], requiresReason: false },
  { from: "paid_escrowed", to: "released_to_lawyer", validRoles: ["admin"], requiresReason: false },
  { from: "paid_escrowed", to: "refunded_full", validRoles: ["admin"], requiresReason: true },
  { from: "paid_escrowed", to: "refunded_partial", validRoles: ["admin"], requiresReason: true },
  { from: "released_to_lawyer", to: "refunded_partial", validRoles: ["admin"], requiresReason: true },
  { from: "paid_escrowed", to: "chargeback", validRoles: ["admin", "system"], requiresReason: true },
  { from: "released_to_lawyer", to: "chargeback", validRoles: ["admin", "system"], requiresReason: true },
];

export function isValidTransition(
  fromState: PaymentState, 
  toState: PaymentState, 
  role: "admin" | "system"
): boolean {
  const transition = VALID_TRANSITIONS.find(
    t => t.from === fromState && t.to === toState
  );
  return transition ? transition.validRoles.includes(role) : false;
}

export function getAvailableTransitions(
  currentState: PaymentState, 
  role: "admin" | "system"
): PaymentState[] {
  return VALID_TRANSITIONS
    .filter(t => t.from === currentState && t.validRoles.includes(role))
    .map(t => t.to);
}

export interface TransitionResult {
  success: boolean;
  payment?: Payment;
  error?: string;
}

export async function transitionPaymentState(
  paymentId: number,
  targetState: PaymentState,
  role: "admin" | "system",
  reason?: string
): Promise<TransitionResult> {
  const [payment] = await db.select().from(payments)
    .where(eq(payments.id, paymentId));

  if (!payment) {
    return { success: false, error: "Payment not found" };
  }

  const currentState = (payment.state || "unpaid") as PaymentState;

  if (!isValidTransition(currentState, targetState, role)) {
    return { 
      success: false, 
      error: `Invalid transition from ${currentState} to ${targetState} for role ${role}` 
    };
  }

  const transition = VALID_TRANSITIONS.find(
    t => t.from === currentState && t.to === targetState
  );

  if (transition?.requiresReason && !reason) {
    return { success: false, error: "This transition requires a reason" };
  }

  const updateData: Partial<Payment> = {
    state: targetState,
  };

  switch (targetState) {
    case "paid_escrowed":
      updateData.status = "completed";
      updateData.escrowedAt = new Date();
      break;
    case "released_to_lawyer":
      updateData.releasedAt = new Date();
      break;
    case "refunded_full":
    case "refunded_partial":
    case "chargeback":
      updateData.refundedAt = new Date();
      updateData.refundReason = reason;
      break;
  }

  const [updated] = await db.update(payments)
    .set(updateData)
    .where(eq(payments.id, paymentId))
    .returning();

  if (targetState === "paid_escrowed" && payment.applicationId) {
    await db.update(companyApplications)
      .set({ 
        paymentState: targetState,
        paymentStateUpdatedAt: new Date(),
      })
      .where(eq(companyApplications.id, payment.applicationId));
  }

  return { success: true, payment: updated };
}

export async function handlePaystackWebhook(
  reference: string,
  status: "success" | "failed",
  paystackData: Record<string, any>
): Promise<TransitionResult> {
  const [payment] = await db.select().from(payments)
    .where(eq(payments.paystackReference, reference));

  if (!payment) {
    return { success: false, error: "Payment not found for reference" };
  }

  if (status === "success") {
    return transitionPaymentState(payment.id, "paid_escrowed", "system");
  } else {
    return { success: true, payment, error: "Payment failed - no state change needed" };
  }
}

export async function releaseToLawyer(
  applicationId: number,
  lawyerUserId: string,
  lawyerFeeKobo: number
): Promise<TransitionResult> {
  const [payment] = await db.select().from(payments)
    .where(eq(payments.applicationId, applicationId));

  if (!payment) {
    return { success: false, error: "No payment found for this application" };
  }

  const result = await transitionPaymentState(payment.id, "released_to_lawyer", "admin");

  if (result.success && result.payment) {
    await db.insert(payoutLedger).values({
      paymentId: result.payment.id,
      lawyerUserId,
      amountKobo: lawyerFeeKobo,
      status: "pending",
    });

    await db.update(companyApplications)
      .set({ 
        paymentState: "released_to_lawyer",
        paymentStateUpdatedAt: new Date(),
      })
      .where(eq(companyApplications.id, applicationId));
  }

  return result;
}

export async function processRefund(
  applicationId: number,
  reason: string,
  isPartial: boolean = false
): Promise<TransitionResult> {
  const [payment] = await db.select().from(payments)
    .where(eq(payments.applicationId, applicationId));

  if (!payment) {
    return { success: false, error: "No payment found for this application" };
  }

  const targetState: PaymentState = isPartial ? "refunded_partial" : "refunded_full";
  const result = await transitionPaymentState(payment.id, targetState, "admin", reason);

  if (result.success) {
    await db.update(companyApplications)
      .set({ 
        paymentState: targetState,
        paymentStateUpdatedAt: new Date(),
      })
      .where(eq(companyApplications.id, applicationId));
  }

  return result;
}

export async function getPaymentState(applicationId: number): Promise<{
  state: PaymentState;
  payment?: Payment;
  availableTransitions: PaymentState[];
}> {
  const [payment] = await db.select().from(payments)
    .where(eq(payments.applicationId, applicationId));

  if (!payment) {
    return {
      state: "unpaid",
      availableTransitions: getAvailableTransitions("unpaid", "admin"),
    };
  }

  const currentState = (payment.state || "unpaid") as PaymentState;

  return {
    state: currentState,
    payment,
    availableTransitions: getAvailableTransitions(currentState, "admin"),
  };
}

