            </CardHeader>
          </Card>
          <Card>
            <CardHeader className="pb-2">
              <CardDescription>To Scan</CardDescription>
              <CardTitle className="text-2xl">{stats?.pendingScan ?? 0}</CardTitle>
            </CardHeader>
          </Card>
          <Card>
