            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {pendingSubscriptions.map((sub) => (
                  <div
                    key={sub.id}
                    className="flex items-center justify-between bg-background rounded-lg p-3 border"
                    data-testid={`pending-sub-${sub.id}`}
