                          <div>
                            <div className="flex items-center gap-2">
                              <p className="font-medium">{item.senderLabel || "Unknown Sender"}</p>
                              {item.isSensitive && (
                                <Badge variant="destructive" className="text-xs">
                                  <AlertTriangle className="h-3 w-3 mr-1" />
