              data-testid="button-submit-intake"
            >
              {intakeMutation.isPending ? <LoadingSpinner size="sm" /> : "Record Mail"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={scanDialogOpen} onOpenChange={setScanDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Record Scan</DialogTitle>
