import { db } from "../db";
import { eq, and, lt, lte, gte } from "drizzle-orm";
import { 
  registeredOfficeSubscriptions,
  notifications,
  auditLogs,
} from "@shared/schema";

// Scheduler for subscription expiry and renewal nudges
// Runs daily checks for expiring/expired subscriptions

export const subscriptionScheduler = {
  // Process expired subscriptions (endDate < today)
  async processExpiredSubscriptions(): Promise<number> {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // Find all active subscriptions that have expired
    const expiredSubscriptions = await db.select()
      .from(registeredOfficeSubscriptions)
      .where(and(
        eq(registeredOfficeSubscriptions.status, "active"),
        lt(registeredOfficeSubscriptions.endDate, today)
      ));

    let expiredCount = 0;

    for (const sub of expiredSubscriptions) {
      // Update status to expired
      await db.update(registeredOfficeSubscriptions)
        .set({ 
          status: "expired",
          updatedAt: new Date()
        })
        .where(eq(registeredOfficeSubscriptions.id, sub.id));

      // Create notification for founder
      await db.insert(notifications).values({
        userId: sub.founderId,
        title: "Registered Office Subscription Expired",
        message: "Your registered office subscription has expired. Your address is no longer active and mail cannot be processed. Renew to reactivate your services.",
        type: "error",
        linkUrl: "/founder/registered-office",
      });

      // Log audit action
      await db.insert(auditLogs).values({
        actorUserId: sub.founderId,
        action: "registered_office_expired",
        entityType: "registered_office_subscription",
        entityId: sub.id.toString(),
        details: { 
          endDate: sub.endDate?.toISOString(),
          tier: sub.tier 
        },
      });

      expiredCount++;
      console.log(`[Scheduler] Expired subscription ${sub.id} for founder ${sub.founderId}`);
    }

    return expiredCount;
  },

  // Send renewal nudge notifications
  async sendRenewalNudges(): Promise<{ sent30d: number; sent7d: number }> {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // Calculate target dates
    const thirtyDaysFromNow = new Date(today);
    thirtyDaysFromNow.setDate(thirtyDaysFromNow.getDate() + 30);

    const sevenDaysFromNow = new Date(today);
    sevenDaysFromNow.setDate(sevenDaysFromNow.getDate() + 7);

    // For simplicity, we'll use a date range approach
    // 30-day notice: endDate is between 29 and 31 days from now
    const thirtyDayStart = new Date(today);
    thirtyDayStart.setDate(thirtyDayStart.getDate() + 29);
    const thirtyDayEnd = new Date(today);
    thirtyDayEnd.setDate(thirtyDayEnd.getDate() + 31);

    // 7-day notice: endDate is between 6 and 8 days from now
    const sevenDayStart = new Date(today);
    sevenDayStart.setDate(sevenDayStart.getDate() + 6);
    const sevenDayEnd = new Date(today);
    sevenDayEnd.setDate(sevenDayEnd.getDate() + 8);

    let sent30d = 0;
    let sent7d = 0;

    // 30-day renewal notices
    const subs30d = await db.select()
      .from(registeredOfficeSubscriptions)
      .where(and(
        eq(registeredOfficeSubscriptions.status, "active"),
        gte(registeredOfficeSubscriptions.endDate, thirtyDayStart),
        lte(registeredOfficeSubscriptions.endDate, thirtyDayEnd)
      ));

    for (const sub of subs30d) {
      await db.insert(notifications).values({
        userId: sub.founderId,
        title: "Registered Office Renewal - 30 Days Notice",
        message: "Your registered office subscription will expire in 30 days. Renew now to ensure uninterrupted service.",
        type: "warning",
        linkUrl: "/founder/registered-office",
      });

      await db.insert(auditLogs).values({
        actorUserId: sub.founderId,
        action: "registered_office_renewal_notice_sent",
        entityType: "registered_office_subscription",
        entityId: sub.id.toString(),
        details: { 
          noticePeriod: "30_days",
          endDate: sub.endDate?.toISOString() 
        },
      });

      sent30d++;
      console.log(`[Scheduler] Sent 30-day renewal notice for subscription ${sub.id}`);
    }

    // 7-day renewal notices
    const subs7d = await db.select()
      .from(registeredOfficeSubscriptions)
      .where(and(
        eq(registeredOfficeSubscriptions.status, "active"),
        gte(registeredOfficeSubscriptions.endDate, sevenDayStart),
        lte(registeredOfficeSubscriptions.endDate, sevenDayEnd)
      ));

    for (const sub of subs7d) {
      await db.insert(notifications).values({
        userId: sub.founderId,
        title: "Registered Office Renewal - 7 Days Notice",
        message: "Your registered office subscription will expire in 7 days. Renew immediately to avoid service interruption.",
        type: "error",
        linkUrl: "/founder/registered-office",
      });

      await db.insert(auditLogs).values({
        actorUserId: sub.founderId,
        action: "registered_office_renewal_notice_sent",
        entityType: "registered_office_subscription",
        entityId: sub.id.toString(),
        details: { 
          noticePeriod: "7_days",
          endDate: sub.endDate?.toISOString() 
        },
      });

      sent7d++;
      console.log(`[Scheduler] Sent 7-day renewal notice for subscription ${sub.id}`);
    }

    return { sent30d, sent7d };
  },

  // Run all scheduled tasks
  async runDailyTasks(): Promise<void> {
    console.log("[Scheduler] Running daily subscription tasks...");

    try {
      const expiredCount = await this.processExpiredSubscriptions();
      console.log(`[Scheduler] Processed ${expiredCount} expired subscriptions`);

      const { sent30d, sent7d } = await this.sendRenewalNudges();
      console.log(`[Scheduler] Sent ${sent30d} 30-day notices, ${sent7d} 7-day notices`);

      console.log("[Scheduler] Daily tasks completed successfully");
    } catch (error) {
      console.error("[Scheduler] Error running daily tasks:", error);
    }
  },
};

// Start scheduler (run daily at midnight)
let schedulerInterval: NodeJS.Timeout | null = null;

export function startSubscriptionScheduler() {
  if (schedulerInterval) {
    console.log("[Scheduler] Scheduler already running");
    return;
  }

  // Run immediately on startup (after a short delay to let DB connect)
  setTimeout(() => {
    subscriptionScheduler.runDailyTasks();
  }, 5000);

  // Then run every 24 hours
  const ONE_DAY_MS = 24 * 60 * 60 * 1000;
  schedulerInterval = setInterval(() => {
    subscriptionScheduler.runDailyTasks();
  }, ONE_DAY_MS);

  console.log("[Scheduler] Subscription scheduler started (runs daily)");
}

export function stopSubscriptionScheduler() {
  if (schedulerInterval) {
    clearInterval(schedulerInterval);
    schedulerInterval = null;
    console.log("[Scheduler] Subscription scheduler stopped");
  }
}

server/services/clarificationService.ts.content:
import { db } from "../db";
import { eq, desc } from "drizzle-orm";
import { 
  clarificationRequests, 
  companyApplications,
  documentFiles,
  users,
  type ClarificationRequest, 
  type InsertClarificationRequest 
} from "@shared/schema";
import { generateClarificationDraft, type ClarificationDraft } from "./aiService";

export interface CreateClarificationInput {
  applicationId: number;
  lawyerId: string;
  founderUserId: string;
  subject: string;
  message: string;
  useAIDraft?: boolean;
  aiDraftJson?: {
    subject?: string;
    message?: string;
    rationale?: string;
    requiredActions?: string[];
  };
}

export async function createClarificationRequest(
  input: CreateClarificationInput
): Promise<ClarificationRequest> {
  const [application] = await db.select().from(companyApplications)
    .where(eq(companyApplications.id, input.applicationId));

  if (!application) {
    throw new Error("Application not found");
  }

  if (application.assignedLawyerUserId !== input.lawyerId) {
    throw new Error("Only the assigned lawyer can create clarification requests");
  }

  const clarificationData: InsertClarificationRequest = {
    applicationId: input.applicationId,
    lawyerUserId: input.lawyerId,
    founderUserId: input.founderUserId,
    subject: input.subject,
    message: input.message,
    status: "open",
    aiDraftJson: input.aiDraftJson,
  };

  const [clarification] = await db.insert(clarificationRequests)
    .values(clarificationData)
    .returning();

  return clarification;
}

export async function sendClarificationRequest(
  clarificationId: number,
  lawyerId: string
): Promise<ClarificationRequest> {
  const [clarification] = await db.select().from(clarificationRequests)
    .where(eq(clarificationRequests.id, clarificationId));

  if (!clarification) {
    throw new Error("Clarification request not found");
  }

  if (clarification.lawyerUserId !== lawyerId) {
    throw new Error("Only the assigned lawyer can send this clarification");
  }

  if (clarification.status !== "open") {
    throw new Error("Can only send clarifications that are in 'open' status");
  }

  const [updated] = await db.update(clarificationRequests)
    .set({
      status: "sent",
      sentAt: new Date(),
    })
    .where(eq(clarificationRequests.id, clarificationId))
    .returning();

  await db.update(companyApplications)
    .set({ 
      status: "clarification_requested",
      updatedAt: new Date(),
    })
    .where(eq(companyApplications.id, clarification.applicationId));

  return updated;
}

export async function generateAIDraft(
  applicationId: number,
  lawyerId: string,
  issueDescription: string
): Promise<{ draft: ClarificationDraft | null }> {
  const [application] = await db.select().from(companyApplications)
    .where(eq(companyApplications.id, applicationId));

  if (!application) {
    throw new Error("Application not found");
  }

  const [founder] = await db.select().from(users)
    .where(eq(users.id, application.founderUserId));

  const documents = await db.select().from(documentFiles)
    .where(eq(documentFiles.applicationId, applicationId));

  const result = await generateClarificationDraft(
    applicationId,
    lawyerId,
    {
      companyName: application.companyName1 || "Unknown Company",
      founderName: founder ? `${founder.firstName} ${founder.lastName}` : "Founder",
      issue: issueDescription,
      existingDocuments: documents.map(d => d.docType),
    }
  );

  return result;
}

export async function getClarificationsByApplication(
  applicationId: number
): Promise<ClarificationRequest[]> {
  return db.select().from(clarificationRequests)
    .where(eq(clarificationRequests.applicationId, applicationId))
    .orderBy(desc(clarificationRequests.createdAt));
}

export async function getClarificationsByFounder(
  founderUserId: string
): Promise<ClarificationRequest[]> {
  return db.select().from(clarificationRequests)
    .where(eq(clarificationRequests.founderUserId, founderUserId))
    .orderBy(desc(clarificationRequests.createdAt));
}

export async function getClarificationsByLawyer(
  lawyerId: string
): Promise<ClarificationRequest[]> {
  return db.select().from(clarificationRequests)
    .where(eq(clarificationRequests.lawyerUserId, lawyerId))
    .orderBy(desc(clarificationRequests.createdAt));
}

export async function resolveClarification(
  clarificationId: number,
  lawyerId: string
): Promise<ClarificationRequest> {
  const [clarification] = await db.select().from(clarificationRequests)
    .where(eq(clarificationRequests.id, clarificationId));

  if (!clarification) {
    throw new Error("Clarification request not found");
  }

  if (clarification.lawyerUserId !== lawyerId) {
    throw new Error("Only the assigned lawyer can resolve this clarification");
  }

  const [updated] = await db.update(clarificationRequests)
    .set({
      status: "resolved",
      resolvedAt: new Date(),
    })
    .where(eq(clarificationRequests.id, clarificationId))
    .returning();

  const openClarifications = await db.select().from(clarificationRequests)
    .where(eq(clarificationRequests.applicationId, clarification.applicationId))
    .then(rows => rows.filter(r => r.status === "open" || r.status === "sent"));

  if (openClarifications.length === 0) {
    await db.update(companyApplications)
      .set({ 
        status: "under_review",
        updatedAt: new Date(),
      })
      .where(eq(companyApplications.id, clarification.applicationId));
  }

  return updated;
}

export async function getPendingClarificationCount(applicationId: number): Promise<number> {
  const clarifications = await db.select().from(clarificationRequests)
    .where(eq(clarificationRequests.applicationId, applicationId));

  return clarifications.filter(c => c.status === "open" || c.status === "sent").length;
}

client/src/hooks/use-auth.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { getQueryFn } from "../lib/queryClient";

export interface AuthUser {
  id: string;
  email?: string | null;
  firstName?: string | null;
  lastName?: string | null;
  profileImageUrl?: string | null;
  roles?: string[];
}

interface AuthContextValue {
  user: AuthUser | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  logout: () => void;
}

export function useAuth(): AuthContextValue {
  const { data, isLoading, error } = useQuery<AuthUser | null>({
    queryKey: ["/api/auth/user"],
    queryFn: getQueryFn({ on401: "returnNull" }),
    retry: false,
    staleTime: 1000 * 60 * 5,
  });

  const logout = async () => {
    try {
      await fetch("/api/auth/logout", { method: "POST", credentials: "include" });
    } catch (e) {
      // Ignore errors
    }
    window.location.href = "/login";
  };

  return {
    user: data || null,
    isLoading,
    isAuthenticated: !!data && !error,
    logout,
  };
}

client/src/pages/auth/login.tsx.content:
import { useState } from "react";
import { Link, useLocation } from "wouter";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardDescription, CardHeader, CardTitle, CardFooter } from "@/components/ui/card";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { useToast } from "@/hooks/use-toast";
import { ThemeToggle } from "@/components/theme-toggle";
import { Building2, Loader2, Eye, EyeOff } from "lucide-react";

const loginSchema = z.object({
  email: z.string().email("Please enter a valid email address"),
  password: z.string().min(1, "Password is required"),
});

type LoginForm = z.infer<typeof loginSchema>;

export default function LoginPage() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [showResendVerification, setShowResendVerification] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const form = useForm<LoginForm>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      email: "",
      password: "",
    },
  });

  const loginMutation = useMutation({
    mutationFn: async (data: LoginForm) => {
      const res = await apiRequest("POST", "/api/auth/login", data);
      return res.json();
    },
    onSuccess: (data) => {
      toast({ title: "Welcome back!", description: "You have been logged in successfully." });
      queryClient.invalidateQueries({ queryKey: ["/api/auth/user"] });
      setLocation("/");
    },
    onError: (error: any) => {
      const message = error?.message || "Login failed. Please check your credentials.";
      if (message.includes("verify your email")) {
        setShowResendVerification(true);
      }
      toast({ title: "Login failed", description: message, variant: "destructive" });
    },
  });

  const resendMutation = useMutation({
    mutationFn: async (email: string) => {
      const res = await apiRequest("POST", "/api/auth/resend-verification", { email });
      return res.json();
    },
    onSuccess: () => {
      toast({ title: "Verification email sent", description: "Please check your inbox." });
    },
    onError: () => {
      toast({ title: "Failed to send", description: "Please try again later.", variant: "destructive" });
    },
  });

  const onSubmit = (data: LoginForm) => {
    loginMutation.mutate(data);
  };

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <nav className="fixed top-0 left-0 right-0 z-50 backdrop-blur-md bg-background/80 border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16 gap-4">
            <Link href="/">
              <a className="flex items-center gap-2">
                <div className="h-8 w-8 rounded-md bg-primary flex items-center justify-center">
                  <Building2 className="h-5 w-5 text-primary-foreground" />
                </div>
                <span className="font-bold text-xl">Celion One</span>
              </a>
            </Link>
            <ThemeToggle />
          </div>
        </div>
      </nav>

      <div className="flex-1 flex items-center justify-center px-4 pt-20 pb-8">
        <Card className="w-full max-w-md">
          <CardHeader className="space-y-1 text-center">
            <CardTitle className="text-2xl font-bold">Welcome back</CardTitle>
            <CardDescription>
              Sign in to your account to continue
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                <FormField
                  control={form.control}
                  name="email"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Email</FormLabel>
                      <FormControl>
                        <Input
                          type="email"
                          placeholder="you@example.com"
                          data-testid="input-email"
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="password"
                  render={({ field }) => (
                    <FormItem>
                      <div className="flex items-center justify-between">
                        <FormLabel>Password</FormLabel>
                        <Link href="/forgot-password">
                          <a className="text-sm text-primary hover:underline" data-testid="link-forgot-password">
                            Forgot password?
                          </a>
                        </Link>
                      </div>
                      <FormControl>
                        <div className="relative">
                          <Input
                            type={showPassword ? "text" : "password"}
                            placeholder="Enter your password"
                            className="pr-10"
                            data-testid="input-password"
                            {...field}
                          />
                          <button
                            type="button"
                            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                            onClick={() => setShowPassword(!showPassword)}
                            aria-label={showPassword ? "Hide password" : "Show password"}
                            aria-pressed={showPassword}
                            data-testid="button-toggle-password"
                          >
                            {showPassword ? (
                              <EyeOff className="h-4 w-4" />
                            ) : (
                              <Eye className="h-4 w-4" />
                            )}
                          </button>
                        </div>
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {showResendVerification && (
                  <div className="bg-muted/50 p-3 rounded-md text-sm">
                    <p className="text-muted-foreground mb-2">
                      Your email hasn't been verified yet.
                    </p>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={() => resendMutation.mutate(form.getValues("email"))}
                      disabled={resendMutation.isPending}
                      data-testid="button-resend-verification"
                    >
                      {resendMutation.isPending ? (
                        <Loader2 className="h-4 w-4 animate-spin mr-2" />
                      ) : null}
                      Resend verification email
                    </Button>
                  </div>
                )}

                <Button
                  type="submit"
                  className="w-full"
                  disabled={loginMutation.isPending}
                  data-testid="button-login"
                >
                  {loginMutation.isPending ? (
                    <Loader2 className="h-4 w-4 animate-spin mr-2" />
                  ) : null}
                  Sign in
                </Button>
              </form>
            </Form>
          </CardContent>
          <CardFooter className="flex flex-col gap-4">
            <div className="text-sm text-center text-muted-foreground">
              Don't have an account?{" "}
              <Link href="/register">
                <a className="text-primary hover:underline font-medium" data-testid="link-register">
                  Create one
                </a>
              </Link>
            </div>
          </CardFooter>
        </Card>
      </div>
    </div>
  );
}

