import { useState, useEffect, useCallback } from "react";
import { useLocation } from "wouter";
import { useMutation, useQuery } from "@tanstack/react-query";
import { DashboardLayout } from "@/components/dashboard-layout";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { LoadingSpinner } from "@/components/loading-spinner";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { saveDraft, getDraft, deleteDraft, isOnline, onOnlineStatusChange, type ApplicationDraft } from "@/lib/offline-storage";
import {
  Building2,
  ArrowRight,
  ArrowLeft,
  CheckCircle2,
  Sparkles,
  Wifi,
  WifiOff,
  Save,
  MapPin,
  Mail,
  Shield,
} from "lucide-react";

const steps = [
  { id: 1, title: "Company Type", description: "Choose your company structure" },
  { id: 2, title: "Company Names", description: "Propose up to 3 name options" },
  { id: 3, title: "Business Details", description: "Describe your business activities" },
  { id: 4, title: "Address", description: "Registered office address" },
];

const companyTypes = [
  { value: "LTD", label: "Private Limited Company (LTD)", description: "Most common for small to medium businesses" },
  { value: "PLC", label: "Public Limited Company (PLC)", description: "For companies planning to go public" },
  { value: "LLP", label: "Limited Liability Partnership (LLP)", description: "For professional service firms" },
  { value: "Sole_Proprietorship", label: "Business Name (Sole Proprietorship)", description: "For individual business owners" },
];

const nigerianStates = [
  "Abia", "Adamawa", "Akwa Ibom", "Anambra", "Bauchi", "Bayelsa", "Benue", "Borno",
  "Cross River", "Delta", "Ebonyi", "Edo", "Ekiti", "Enugu", "FCT", "Gombe", "Imo",
  "Jigawa", "Kaduna", "Kano", "Katsina", "Kebbi", "Kogi", "Kwara", "Lagos", "Nasarawa",
  "Niger", "Ogun", "Ondo", "Osun", "Oyo", "Plateau", "Rivers", "Sokoto", "Taraba",
  "Yobe", "Zamfara"
];

const DRAFT_ID = "new-application-draft";

export default function NewApplicationPage() {
  const [, navigate] = useLocation();
  const { toast } = useToast();
  const [currentStep, setCurrentStep] = useState(1);
  const [online, setOnline] = useState(isOnline());
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [formData, setFormData] = useState({
    applicationType: "incorporation",
    companyType: "",
    companyName1: "",
    companyName2: "",
    companyName3: "",
    businessDescription: "",
    registeredAddress: {
      line1: "",
      line2: "",
      city: "",
      state: "",
      postalCode: "",
    },
    useRegisteredOffice: false,
    registeredOfficeTier: "" as "" | "office_only" | "office_plus_mail",
  });
  const [aiSuggestions, setAiSuggestions] = useState<any[]>([]);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Fetch registered office options
  const { data: registeredOfficeOptions } = useQuery<{
    tiers: { id: string; name: string; priceNgn: number; description: string; features: string[] }[];
    location: { label: string; city: string; state: string; country: string };
    policyText: string;
    termMonths: number;
  }>({
    queryKey: ["/api/registered-office/options"],
  });

  // Load draft from localStorage on mount
  useEffect(() => {
    const savedDraft = getDraft(DRAFT_ID);
    if (savedDraft && savedDraft.data) {
      let restoredAddress = formData.registeredAddress;
      if (savedDraft.data.registeredAddress) {
        try {
          restoredAddress = typeof savedDraft.data.registeredAddress === 'string'
            ? JSON.parse(savedDraft.data.registeredAddress)
            : savedDraft.data.registeredAddress;
        } catch {
          restoredAddress = formData.registeredAddress;
        }
      }

      setFormData(prev => ({
        ...prev,
        applicationType: savedDraft.data.applicationType || prev.applicationType,
        companyType: savedDraft.data.companyType || prev.companyType,
        companyName1: savedDraft.data.companyName1 || prev.companyName1,
        companyName2: savedDraft.data.companyName2 || prev.companyName2,
        companyName3: savedDraft.data.companyName3 || prev.companyName3,
        businessDescription: savedDraft.data.businessDescription || prev.businessDescription,
        registeredAddress: restoredAddress,
      }));
      setCurrentStep(savedDraft.step);
      toast({
        title: "Draft restored",
        description: "Your previous draft has been loaded.",
      });
    }
  }, []);

  // Track online status
  useEffect(() => {
    return onOnlineStatusChange((isOnline) => {
      setOnline(isOnline);
      if (isOnline) {
        toast({
          title: "Back online",
          description: "Your connection has been restored.",
        });
      } else {
        toast({
          title: "You're offline",
          description: "Changes will be saved locally.",
          variant: "destructive",
        });
      }
    });
  }, []);

  // Auto-save draft when form data or step changes
  const autoSave = useCallback(() => {
    saveDraft({
      id: DRAFT_ID,
      step: currentStep,
      data: {
        applicationType: formData.applicationType,
        companyType: formData.companyType,
        companyName1: formData.companyName1,
        companyName2: formData.companyName2,
        companyName3: formData.companyName3,
        businessDescription: formData.businessDescription,
        registeredAddress: JSON.stringify(formData.registeredAddress),
      },
      updatedAt: new Date().toISOString(),
      synced: false,
    });
    setLastSaved(new Date());
  }, [formData, currentStep]);

  useEffect(() => {
    const timer = setTimeout(autoSave, 1000);
    return () => clearTimeout(timer);
  }, [formData, currentStep, autoSave]);

  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      const response = await apiRequest("POST", "/api/applications", {
        applicationType: data.applicationType,
        companyType: data.companyType,
        companyName1: data.companyName1,
        companyName2: data.companyName2,
        companyName3: data.companyName3,
        businessDescription: data.businessDescription,
        registeredAddress: data.useRegisteredOffice ? null : data.registeredAddress,
      });
      const app = await response.json();

      // If using registered office, call the selection API
      if (data.useRegisteredOffice && data.registeredOfficeTier) {
        await apiRequest("POST", "/api/registered-office/select", {
          applicationId: app.id,
          tier: data.registeredOfficeTier,
        });
      }

      return app;
    },
    onSuccess: async (app) => {
      deleteDraft(DRAFT_ID);
      queryClient.invalidateQueries({ queryKey: ["/api/founder/applications"] });
      queryClient.invalidateQueries({ queryKey: ["/api/founder/dashboard"] });
      toast({
        title: "Application created",
        description: formData.useRegisteredOffice 
          ? "Your application has been saved with registered office selection."
          : "Your application has been saved as a draft.",
      });
      navigate(`/applications/${app.id}`);
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to create application. Please try again.",
        variant: "destructive",
      });
    },
  });

  const fetchAiSuggestions = async () => {
    if (!formData.businessDescription.trim()) return;

    setIsLoadingAi(true);
    try {
      const response = await apiRequest("POST", "/api/legal-ai/suggest-activities", {
        businessDescription: formData.businessDescription,
        companyType: formData.companyType,
      });
      const data = await response.json();
      setAiSuggestions(data.suggestions || []);
    } catch (error) {
      console.error("AI suggestions error:", error);
    } finally {
      setIsLoadingAi(false);
    }
  };

  const updateFormData = (field: string, value: any) => {
    setFormData((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const updateAddress = (field: string, value: string) => {
    setFormData((prev) => ({
      ...prev,
      registeredAddress: {
        ...prev.registeredAddress,
        [field]: value,
      },
    }));
  };

  const canProceed = () => {
    switch (currentStep) {
      case 1:
        return !!formData.companyType;
      case 2:
        return !!formData.companyName1;
      case 3:
        return !!formData.businessDescription;
      case 4:
        if (formData.useRegisteredOffice) {
          return !!formData.registeredOfficeTier;
        }
        return !!formData.registeredAddress.line1 && !!formData.registeredAddress.city && !!formData.registeredAddress.state;
      default:
        return false;
    }
  };

  const handleNext = () => {
    if (currentStep < 4) {
      setCurrentStep(currentStep + 1);
    } else {
      createMutation.mutate(formData);
    }
  };

  const handleBack = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  return (
    <DashboardLayout 
      role="founder" 
      breadcrumbs={[
        { label: "Dashboard", href: "/founder/dashboard" },
        { label: "Applications", href: "/founder/applications" },
        { label: "New Application" }
      ]}
    >
      <div className="max-w-3xl mx-auto space-y-8">
        <div className="flex items-start justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold">New Company Registration</h1>
            <p className="text-muted-foreground">
              Complete the following steps to start your company incorporation
            </p>
          </div>
          <div className="flex items-center gap-2">
            {!online && (
              <Badge variant="destructive" className="flex items-center gap-1" data-testid="badge-offline">
                <WifiOff className="h-3 w-3" />
                Offline
              </Badge>
            )}
            {lastSaved && (
              <Badge variant="secondary" className="flex items-center gap-1" data-testid="badge-saved">
                <Save className="h-3 w-3" />
                Saved
              </Badge>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2">
          {steps.map((step, index) => (
            <div key={step.id} className="flex items-center flex-1">
              <div className={`flex items-center gap-2 ${index > 0 ? "flex-1" : ""}`}>
                {index > 0 && (
                  <div className={`h-0.5 flex-1 ${currentStep > step.id - 1 ? "bg-primary" : "bg-muted"}`} />
                )}
                <div
                  className={`h-8 w-8 rounded-full flex items-center justify-center text-sm font-medium shrink-0 ${
                    currentStep > step.id
                      ? "bg-primary text-primary-foreground"
                      : currentStep === step.id
                      ? "bg-primary text-primary-foreground"
                      : "bg-muted text-muted-foreground"
                  }`}
                >
                  {currentStep > step.id ? <CheckCircle2 className="h-4 w-4" /> : step.id}
                </div>
              </div>
            </div>
          ))}
        </div>

        <Card>
          <CardHeader>
            <CardTitle>{steps[currentStep - 1].title}</CardTitle>
            <CardDescription>{steps[currentStep - 1].description}</CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            {currentStep === 1 && (
              <div className="grid gap-4">
                {companyTypes.map((type) => (
                  <div
                    key={type.value}
                    className={`p-4 rounded-lg border-2 cursor-pointer transition-all hover-elevate ${
                      formData.companyType === type.value
                        ? "border-primary bg-primary/5"
                        : "border-transparent bg-muted/50"
                    }`}
                    onClick={() => updateFormData("companyType", type.value)}
                    data-testid={`company-type-${type.value}`}
                  >
                    <div className="flex items-center gap-4">
                      <div className={`h-10 w-10 rounded-lg flex items-center justify-center ${
                        formData.companyType === type.value ? "bg-primary/20" : "bg-muted"
                      }`}>
                        <Building2 className={`h-5 w-5 ${
                          formData.companyType === type.value ? "text-primary" : "text-muted-foreground"
                        }`} />
                      </div>
                      <div>
                        <h3 className="font-medium">{type.label}</h3>
                        <p className="text-sm text-muted-foreground">{type.description}</p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {currentStep === 2 && (
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="companyName1">Preferred Company Name *</Label>
                  <Input
                    id="companyName1"
                    placeholder="e.g., TechVentures Nigeria"
                    value={formData.companyName1}
                    onChange={(e) => updateFormData("companyName1", e.target.value)}
                    data-testid="input-company-name-1"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="companyName2">Alternative Name 1 (Optional)</Label>
                  <Input
                    id="companyName2"
                    placeholder="Second choice"
                    value={formData.companyName2}
                    onChange={(e) => updateFormData("companyName2", e.target.value)}
                    data-testid="input-company-name-2"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="companyName3">Alternative Name 2 (Optional)</Label>
                  <Input
                    id="companyName3"
                    placeholder="Third choice"
                    value={formData.companyName3}
                    onChange={(e) => updateFormData("companyName3", e.target.value)}
                    data-testid="input-company-name-3"
                  />
                </div>
                <p className="text-sm text-muted-foreground">
                  CAC will check name availability and register the first available option.
                </p>
              </div>
            )}

            {currentStep === 3 && (
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="businessDescription">Business Description *</Label>
                  <Textarea
                    id="businessDescription"
                    placeholder="Describe what your company will do..."
                    rows={4}
                    value={formData.businessDescription}
                    onChange={(e) => updateFormData("businessDescription", e.target.value)}
                    data-testid="input-business-description"
                  />
                </div>

                <Button
                  type="button"
                  variant="outline"
                  onClick={fetchAiSuggestions}
                  disabled={!formData.businessDescription.trim() || isLoadingAi}
                  className="gap-2"
                  data-testid="button-ai-suggest"
                >
                  {isLoadingAi ? (
                    <LoadingSpinner size="sm" />
                  ) : (
                    <Sparkles className="h-4 w-4" />
                  )}
                  Suggest CAC Activities
                </Button>

                {aiSuggestions.length > 0 && (
                  <Card className="bg-primary/5 border-primary/20">
                    <CardHeader className="pb-2">
                      <CardTitle className="text-sm flex items-center gap-2">
                        <Sparkles className="h-4 w-4 text-primary" />
                        AI-Suggested CAC Activities
                      </CardTitle>
                      <CardDescription className="text-xs">
                        These are suggestions only, not legal advice. Your lawyer will review.
                      </CardDescription>
                    </CardHeader>
                    <CardContent>
                      <ul className="space-y-2 text-sm">
                        {aiSuggestions.map((suggestion, index) => (
                          <li key={index} className="flex items-start gap-2">
                            <CheckCircle2 className="h-4 w-4 text-primary mt-0.5 shrink-0" />
                            <span>{suggestion.activity || suggestion}</span>
                          </li>
                        ))}
                      </ul>
                    </CardContent>
                  </Card>
                )}
              </div>
            )}

            {currentStep === 4 && (
              <div className="space-y-6">
                <div className="space-y-3">
                  <Label className="text-base font-medium">Choose Address Type</Label>
                  <RadioGroup 
                    value={formData.useRegisteredOffice ? "celion" : "own"}
                    onValueChange={(value) => {
                      updateFormData("useRegisteredOffice", value === "celion");
                      if (value === "own") {
                        updateFormData("registeredOfficeTier", "");
                      }
                    }}
                    className="space-y-3"
                  >
                    <div className="flex items-start space-x-3 border rounded-lg p-4 hover-elevate cursor-pointer" onClick={() => updateFormData("useRegisteredOffice", false)}>
                      <RadioGroupItem value="own" id="address-own" data-testid="radio-address-own" />
                      <div className="flex-1">
                        <Label htmlFor="address-own" className="font-medium cursor-pointer">Use My Own Address</Label>
                        <p className="text-sm text-muted-foreground mt-1">Provide your own registered office address</p>
                      </div>
                    </div>
                    <div className="flex items-start space-x-3 border rounded-lg p-4 hover-elevate cursor-pointer bg-primary/5 border-primary/30" onClick={() => updateFormData("useRegisteredOffice", true)}>
                      <RadioGroupItem value="celion" id="address-celion" data-testid="radio-address-celion" />
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <Label htmlFor="address-celion" className="font-medium cursor-pointer">Use Celion Registered Office</Label>
                          <Badge variant="secondary" className="text-xs">Ikoyi, Lagos</Badge>
                        </div>
                        <p className="text-sm text-muted-foreground mt-1">
                          {registeredOfficeOptions?.location.label || "Premium business address in Ikoyi, Lagos"}
                        </p>
                      </div>
                    </div>
                  </RadioGroup>
                </div>

                {formData.useRegisteredOffice && registeredOfficeOptions && (
                  <div className="space-y-4">
                    <div className="bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 rounded-lg p-3 text-sm">
                      <div className="flex items-start gap-2">
                        <Shield className="h-4 w-4 text-amber-600 mt-0.5" />
                        <p className="text-amber-800 dark:text-amber-200">{registeredOfficeOptions.policyText}</p>
                      </div>
                    </div>

                    <Label className="text-sm font-medium">Select Service Tier</Label>
                    <div className="grid gap-4 md:grid-cols-2">
                      {registeredOfficeOptions.tiers.map((tier) => (
                        <Card
                          key={tier.id}
                          className={`cursor-pointer transition-all hover-elevate ${
                            formData.registeredOfficeTier === tier.id
                              ? "border-primary ring-2 ring-primary/20"
                              : "hover:border-primary/50"
                          }`}
                          onClick={() => updateFormData("registeredOfficeTier", tier.id as "office_only" | "office_plus_mail")}
                          data-testid={`card-tier-${tier.id}`}
                        >
                          <CardHeader className="pb-2">
                            <div className="flex justify-between items-start">
                              <CardTitle className="text-base">{tier.name}</CardTitle>
                              {formData.registeredOfficeTier === tier.id && (
                                <CheckCircle2 className="h-5 w-5 text-primary" />
                              )}
                            </div>
                            <CardDescription>{tier.description}</CardDescription>
                          </CardHeader>
                          <CardContent className="space-y-3">
                            <p className="text-2xl font-bold text-primary">
                              ₦{tier.priceNgn.toLocaleString()}<span className="text-sm font-normal text-muted-foreground">/year</span>
                            </p>
                            <ul className="space-y-1.5 text-sm">
                              {tier.features.map((feature, idx) => (
                                <li key={idx} className="flex items-start gap-2">
                                  <CheckCircle2 className="h-4 w-4 text-primary shrink-0 mt-0.5" />
                                  <span>{feature}</span>
                                </li>
                              ))}
                            </ul>
                          </CardContent>
                        </Card>
                      ))}
                    </div>
                  </div>
                )}

                {!formData.useRegisteredOffice && (
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <Label htmlFor="line1">Street Address *</Label>
                      <Input
                        id="line1"
                        placeholder="123 Business Street"
                        value={formData.registeredAddress.line1}
                        onChange={(e) => updateAddress("line1", e.target.value)}
                        data-testid="input-address-line1"
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="line2">Address Line 2</Label>
                      <Input
                        id="line2"
                        placeholder="Suite, floor, building name (optional)"
                        value={formData.registeredAddress.line2}
                        onChange={(e) => updateAddress("line2", e.target.value)}
                        data-testid="input-address-line2"
                      />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <Label htmlFor="city">City *</Label>
                        <Input
                          id="city"
                          placeholder="Lagos"
                          value={formData.registeredAddress.city}
                          onChange={(e) => updateAddress("city", e.target.value)}
                          data-testid="input-address-city"
                        />
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="state">State *</Label>
                        <Select
                          value={formData.registeredAddress.state}
                          onValueChange={(value) => updateAddress("state", value)}
                        >
                          <SelectTrigger data-testid="select-address-state">
                            <SelectValue placeholder="Select state" />
                          </SelectTrigger>
                          <SelectContent>
                            {nigerianStates.map((state) => (
                              <SelectItem key={state} value={state}>
                                {state}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="postalCode">Postal Code</Label>
                      <Input
                        id="postalCode"
                        placeholder="100001"
                        value={formData.registeredAddress.postalCode}
                        onChange={(e) => updateAddress("postalCode", e.target.value)}
                        data-testid="input-address-postal"
                      />
                    </div>
                  </div>
                )}
              </div>
            )}

            <div className="flex items-center justify-between pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={handleBack}
                disabled={currentStep === 1}
                data-testid="button-back"
              >
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back
              </Button>
              <Button
                type="button"
                onClick={handleNext}
                disabled={!canProceed() || createMutation.isPending}
                data-testid="button-next"
              >
                {createMutation.isPending ? (
                  <>
                    <LoadingSpinner size="sm" className="mr-2" />
                    Creating...
                  </>
                ) : currentStep === 4 ? (
                  "Create Application"
                ) : (
                  <>
                    Next
                    <ArrowRight className="h-4 w-4 ml-2" />
                  </>
                )}
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    </DashboardLayout>
  );
}

client/src/pages/admin/receipts.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { DashboardLayout } from "@/components/dashboard-layout";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { LoadingSpinner } from "@/components/loading-spinner";
import { EmptyState } from "@/components/empty-state";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Receipt,
  Search,
  Filter,
  Plus,
  XCircle,
  CheckCircle2,
  Ban,
} from "lucide-react";
import type { VerificationReceipt, CompanyApplication } from "@shared/schema";

interface ReceiptWithApplication extends VerificationReceipt {
  companyName?: string;
}

export default function AdminReceipts() {
  const { toast } = useToast();
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [issueDialogOpen, setIssueDialogOpen] = useState(false);
  const [revokeDialogOpen, setRevokeDialogOpen] = useState(false);
  const [selectedReceipt, setSelectedReceipt] = useState<ReceiptWithApplication | null>(null);
  const [revokeReason, setRevokeReason] = useState("");

  const [newReceipt, setNewReceipt] = useState({
    applicationId: "",
    scope: "incorporation",
    receiptNumber: "",
    issuedBy: "celion",
  });

  const { data: receipts, isLoading } = useQuery<ReceiptWithApplication[]>({
    queryKey: ["/api/admin/receipts"],
  });

  const { data: applications } = useQuery<CompanyApplication[]>({
    queryKey: ["/api/admin/applications"],
  });

  const issueMutation = useMutation({
    mutationFn: async (data: typeof newReceipt) => {
      return apiRequest("POST", "/api/admin/receipts", {
        applicationId: parseInt(data.applicationId),
        scope: data.scope,
        receiptNumber: data.receiptNumber,
        issuedBy: data.issuedBy,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/receipts"] });
      toast({ title: "Receipt issued successfully" });
      setIssueDialogOpen(false);
      setNewReceipt({
        applicationId: "",
        scope: "incorporation",
        receiptNumber: "",
        issuedBy: "celion",
      });
    },
    onError: () => {
      toast({ title: "Failed to issue receipt", variant: "destructive" });
    },
  });

  const revokeMutation = useMutation({
    mutationFn: async ({ id, reason }: { id: number; reason: string }) => {
      return apiRequest("POST", `/api/admin/receipts/${id}/revoke`, { reason });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/receipts"] });
      toast({ title: "Receipt revoked successfully" });
      setRevokeDialogOpen(false);
      setSelectedReceipt(null);
      setRevokeReason("");
    },
    onError: () => {
      toast({ title: "Failed to revoke receipt", variant: "destructive" });
    },
  });

  const filteredReceipts = receipts?.filter((receipt) => {
    const matchesSearch = !searchQuery || 
      receipt.receiptNumber?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      receipt.applicationId?.toString().includes(searchQuery) ||
      receipt.companyName?.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus = statusFilter === "all" || 
      (statusFilter === "active" && !receipt.revokedAt) ||
      (statusFilter === "revoked" && receipt.revokedAt);
    return matchesSearch && matchesStatus;
  });

  const formatDate = (date: Date | string | null) => {
    if (!date) return "—";
    return new Date(date).toLocaleDateString("en-NG", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  const getScopeLabel = (scope: string) => {
    const labels: Record<string, string> = {
      identity: "Identity Verification",
      incorporation: "Incorporation",
      post_incorporation: "Post Incorporation",
      document_bundle: "Document Bundle",
    };
    return labels[scope] || scope;
  };

  return (
    <DashboardLayout 
      role="admin" 
      breadcrumbs={[{ label: "Dashboard", href: "/admin/dashboard" }, { label: "Receipts" }]}
    >
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold">Verification Receipts</h1>
            <p className="text-muted-foreground">
              Issue and manage verification receipts for completed applications
            </p>
          </div>
          <Button onClick={() => setIssueDialogOpen(true)} data-testid="button-issue-receipt">
            <Plus className="h-4 w-4 mr-2" />
            Issue Receipt
          </Button>
        </div>

        <div className="flex flex-col sm:flex-row gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search by receipt number, company, or application ID..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10"
              data-testid="input-search"
            />
          </div>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-full sm:w-40" data-testid="select-status-filter">
              <Filter className="h-4 w-4 mr-2" />
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Receipts</SelectItem>
              <SelectItem value="active">Active</SelectItem>
              <SelectItem value="revoked">Revoked</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {isLoading ? (
          <div className="flex justify-center py-12">
            <LoadingSpinner size="lg" />
          </div>
        ) : !filteredReceipts?.length ? (
          <EmptyState
            icon={Receipt}
            title="No receipts found"
            description="Issue receipts for completed applications to track verification status."
          />
        ) : (
          <div className="grid gap-4">
            {filteredReceipts.map((receipt) => (
              <Card key={receipt.id} data-testid={`receipt-${receipt.id}`}>
                <CardContent className="p-6">
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                    <div className="flex items-start gap-4">
                      <div className={`h-12 w-12 rounded-lg flex items-center justify-center shrink-0 ${
                        receipt.revokedAt ? "bg-destructive/10" : "bg-primary/10"
                      }`}>
                        <Receipt className={`h-6 w-6 ${
                          receipt.revokedAt ? "text-destructive" : "text-primary"
                        }`} />
                      </div>
                      <div className="min-w-0 space-y-1">
                        <div className="flex items-center gap-2 flex-wrap">
                          <h3 className="font-semibold">
                            {receipt.receiptNumber || `Receipt #${receipt.id}`}
                          </h3>
                          <Badge variant={receipt.revokedAt ? "destructive" : "default"}>
                            {receipt.revokedAt ? "Revoked" : "Active"}
                          </Badge>
                        </div>
                        <p className="text-sm text-muted-foreground">
                          {getScopeLabel(receipt.scope || "")}
                        </p>
                        <div className="text-sm text-muted-foreground">
                          <span>Application #{receipt.applicationId}</span>
                          {receipt.companyName && (
                            <>
                              <span> &bull; </span>
                              <span>{receipt.companyName}</span>
                            </>
                          )}
                        </div>
                        {receipt.revokedAt && receipt.revocationReason && (
                          <p className="text-sm text-destructive mt-2">
                            Revoked: {receipt.revocationReason}
                          </p>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-4 sm:shrink-0">
                      <div className="text-sm text-muted-foreground">
                        Issued: {formatDate(receipt.issuedAt)}
                      </div>
                      {!receipt.revokedAt && (
                        <Button 
                          variant="outline" 
                          size="sm"
                          onClick={() => {
                            setSelectedReceipt(receipt);
                            setRevokeDialogOpen(true);
                          }}
                          data-testid={`button-revoke-${receipt.id}`}
                        >
                          <Ban className="h-4 w-4 mr-1" />
                          Revoke
                        </Button>
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>

      <Dialog open={issueDialogOpen} onOpenChange={setIssueDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Issue Verification Receipt</DialogTitle>
            <DialogDescription>
              Create a new verification receipt for a completed application.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="applicationId">Application</Label>
              <Select 
                value={newReceipt.applicationId} 
                onValueChange={(value) => setNewReceipt({ ...newReceipt, applicationId: value })}
              >
                <SelectTrigger data-testid="select-application">
                  <SelectValue placeholder="Select an application" />
                </SelectTrigger>
                <SelectContent>
                  {applications?.filter(app => app.status === "completed").map((app) => (
                    <SelectItem key={app.id} value={app.id.toString()}>
                      #{app.id} - {app.companyName1 || "Untitled"}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="scope">Scope</Label>
              <Select 
                value={newReceipt.scope} 
                onValueChange={(value) => setNewReceipt({ ...newReceipt, scope: value })}
              >
                <SelectTrigger data-testid="select-scope">
                  <SelectValue placeholder="Select scope" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="identity">Identity Verification</SelectItem>
                  <SelectItem value="incorporation">Incorporation</SelectItem>
                  <SelectItem value="post_incorporation">Post Incorporation</SelectItem>
                  <SelectItem value="document_bundle">Document Bundle</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="receiptNumber">Receipt Number</Label>
              <Input
                id="receiptNumber"
                placeholder="e.g., CAC/IT/NO-123456"
                value={newReceipt.receiptNumber}
                onChange={(e) => setNewReceipt({ ...newReceipt, receiptNumber: e.target.value })}
                data-testid="input-receipt-number"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="issuedBy">Issued By</Label>
              <Select 
                value={newReceipt.issuedBy} 
                onValueChange={(value) => setNewReceipt({ ...newReceipt, issuedBy: value })}
              >
                <SelectTrigger data-testid="select-issued-by">
                  <SelectValue placeholder="Select issuer" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="celion">Celion One</SelectItem>
                  <SelectItem value="lawyer_proxy">Lawyer Proxy</SelectItem>
                  <SelectItem value="agency">Agency</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIssueDialogOpen(false)}>
              Cancel
            </Button>
            <Button 
              onClick={() => issueMutation.mutate(newReceipt)}
              disabled={!newReceipt.applicationId || !newReceipt.receiptNumber || issueMutation.isPending}
              data-testid="button-confirm-issue"
            >
              {issueMutation.isPending ? <LoadingSpinner size="sm" /> : "Issue Receipt"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={revokeDialogOpen} onOpenChange={setRevokeDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Revoke Receipt</DialogTitle>
            <DialogDescription>
              This will permanently mark the receipt as revoked. Please provide a reason.
            </DialogDescription>
          </DialogHeader>
          <div className="py-4">
            <Label htmlFor="revokeReason">Reason for Revocation</Label>
            <Textarea
              id="revokeReason"
              placeholder="Explain why this receipt is being revoked..."
              value={revokeReason}
              onChange={(e) => setRevokeReason(e.target.value)}
              className="mt-2"
              data-testid="input-revoke-reason"
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setRevokeDialogOpen(false)}>
              Cancel
            </Button>
            <Button 
              variant="destructive"
              onClick={() => {
                if (selectedReceipt) {
                  revokeMutation.mutate({ id: selectedReceipt.id, reason: revokeReason });
                }
              }}
              disabled={!revokeReason || revokeMutation.isPending}
              data-testid="button-confirm-revoke"
            >
              {revokeMutation.isPending ? <LoadingSpinner size="sm" /> : "Revoke Receipt"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </DashboardLayout>
  );
}

