import { useEffect, useState } from "react";
import { Link, useLocation, useSearch } from "wouter";
import { useMutation } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ThemeToggle } from "@/components/theme-toggle";
import { Building2, Loader2, CheckCircle, XCircle } from "lucide-react";

export default function VerifyEmailPage() {
  const [, setLocation] = useLocation();
  const searchString = useSearch();
  const [status, setStatus] = useState<"loading" | "success" | "error">("loading");
  const [errorMessage, setErrorMessage] = useState("");

  const verifyMutation = useMutation({
    mutationFn: async (token: string) => {
      const res = await apiRequest("POST", "/api/auth/verify-email", { token });
      return res.json();
    },
    onSuccess: () => {
      setStatus("success");
    },
    onError: (error: any) => {
      setStatus("error");
      setErrorMessage(error?.message || "Verification failed. Please try again.");
    },
  });

  useEffect(() => {
    const params = new URLSearchParams(searchString);
    const token = params.get("token");

    if (token) {
      verifyMutation.mutate(token);
    } else {
      setStatus("error");
      setErrorMessage("No verification token provided.");
    }
  }, [searchString]);

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <nav className="fixed top-0 left-0 right-0 z-50 backdrop-blur-md bg-background/80 border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16 gap-4">
            <Link href="/">
              <a className="flex items-center gap-2">
                <div className="h-8 w-8 rounded-md bg-primary flex items-center justify-center">
                  <Building2 className="h-5 w-5 text-primary-foreground" />
                </div>
                <span className="font-bold text-xl">Celion One</span>
              </a>
            </Link>
            <ThemeToggle />
          </div>
        </div>
      </nav>

      <div className="flex-1 flex items-center justify-center px-4 pt-20 pb-8">
        <Card className="w-full max-w-md text-center">
          {status === "loading" && (
            <>
              <CardHeader className="space-y-4">
                <div className="mx-auto w-16 h-16 bg-muted rounded-full flex items-center justify-center">
                  <Loader2 className="h-8 w-8 text-muted-foreground animate-spin" />
                </div>
                <CardTitle className="text-2xl font-bold">Verifying your email</CardTitle>
                <CardDescription className="text-base">
                  Please wait while we verify your email address...
                </CardDescription>
              </CardHeader>
            </>
          )}

          {status === "success" && (
            <>
              <CardHeader className="space-y-4">
                <div className="mx-auto w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center">
                  <CheckCircle className="h-8 w-8 text-primary" />
                </div>
                <CardTitle className="text-2xl font-bold">Email verified!</CardTitle>
                <CardDescription className="text-base">
                  Your email has been verified successfully. You can now log in to your account.
                </CardDescription>
              </CardHeader>
              <CardContent>
                <Button onClick={() => setLocation("/login")} data-testid="button-goto-login">
                  Go to Login
                </Button>
              </CardContent>
            </>
          )}

          {status === "error" && (
            <>
              <CardHeader className="space-y-4">
                <div className="mx-auto w-16 h-16 bg-destructive/10 rounded-full flex items-center justify-center">
                  <XCircle className="h-8 w-8 text-destructive" />
                </div>
                <CardTitle className="text-2xl font-bold">Verification failed</CardTitle>
                <CardDescription className="text-base">
                  {errorMessage}
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <p className="text-sm text-muted-foreground">
                  The verification link may have expired or already been used.
                </p>
                <div className="flex flex-col gap-2">
                  <Button variant="outline" onClick={() => setLocation("/login")} data-testid="button-goto-login">
                    Go to Login
                  </Button>
                </div>
              </CardContent>
            </>
          )}
        </Card>
      </div>
    </div>
  );
}

client/src/pages/founder/mail.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { DashboardLayout } from "@/components/dashboard-layout";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { LoadingSpinner } from "@/components/loading-spinner";
import { EmptyState } from "@/components/empty-state";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Link } from "wouter";
import {
  Mail,
  Package,
  CheckCircle2,
  Clock,
  AlertTriangle,
  FileText,
  ExternalLink,
  Settings,
  Shield,
  Inbox,
  Eye,
  Forward,
  Trash2,
  Building2,
  Info,
  FileCheck,
  Calendar,
} from "lucide-react";

interface MailPreference {
  id: number;
  preferenceType: "scan_all" | "approve_before_scan" | "forward_only";
  forwardingAddress: string | null;
  sensitiveAutoEscalate: boolean;
}

interface MailItem {
  id: number;
  status: string;
  receivedAt: string;
  senderLabel: string | null;
  itemType: string;
  scannedFileUrl: string | null;
  forwardedAt: string | null;
  trackingNumber: string | null;
}

interface MailData {
  preferences: MailPreference | null;
  mailItems: MailItem[];
  pendingApprovals: number;
}

interface SubscriptionData {
  subscription: {
    tier: string;
    status: string;
  } | null;
}

interface ServicePolicy {
  mailItemsIncluded: number;
  storageRetentionDays: number;
  officialMailOnly: boolean;
}

const preferenceOptions = [
  {
    value: "scan_all",
    title: "Scan All Mail",
    description: "Automatically scan and deliver all mail digitally to your inbox",
    icon: Eye,
  },
  {
    value: "approve_before_scan",
    title: "Approve Before Scan",
    description: "Review mail before deciding to scan, forward, or discard",
    icon: CheckCircle2,
  },
  {
    value: "forward_only",
    title: "Forward Only",
    description: "Forward all mail to a physical address without scanning",
    icon: Forward,
  },
];

export default function FounderMailPage() {
  const { toast } = useToast();
  const [selectedPreference, setSelectedPreference] = useState<string>("");
  const [sensitiveEscalate, setSensitiveEscalate] = useState(false);

  const { data: subscription, isLoading: loadingSubscription } = useQuery<SubscriptionData>({
    queryKey: ["/api/registered-office/subscription"],
  });

  const { data: mailData, isLoading: loadingMail } = useQuery<MailData>({
    queryKey: ["/api/registered-office/mail"],
    enabled: subscription?.subscription?.tier === "office_plus_mail" && subscription?.subscription?.status === "active",
  });

  const { data: servicePolicy } = useQuery<ServicePolicy>({
    queryKey: ["/api/registered-office/service-policy"],
  });

  const updatePreferenceMutation = useMutation({
    mutationFn: async (data: { preferenceType: string; sensitiveAutoEscalate: boolean }) => {
      return apiRequest("POST", "/api/registered-office/preferences", data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/registered-office/mail"] });
      toast({
        title: "Preferences updated",
        description: "Your mail handling preferences have been saved.",
      });
    },
    onError: () => {
      toast({
        title: "Update failed",
        description: "Please try again.",
        variant: "destructive",
      });
    },
  });

  const approvalMutation = useMutation({
    mutationFn: async ({ itemId, action }: { itemId: number; action: string }) => {
      return apiRequest("POST", `/api/registered-office/mail/${itemId}/approve`, { action });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/registered-office/mail"] });
      toast({
        title: "Action completed",
        description: "Mail item has been processed.",
      });
    },
    onError: () => {
      toast({
        title: "Action failed",
        description: "Please try again.",
        variant: "destructive",
      });
    },
  });

  const isLoading = loadingSubscription || loadingMail;
  const hasMailService = subscription?.subscription?.tier === "office_plus_mail" && subscription?.subscription?.status === "active";

  // Set initial state from loaded preferences
  if (mailData?.preferences && !selectedPreference) {
    setSelectedPreference(mailData.preferences.preferenceType);
    setSensitiveEscalate(mailData.preferences.sensitiveAutoEscalate);
  }

  const handleSavePreferences = () => {
    if (!selectedPreference) return;
    updatePreferenceMutation.mutate({
      preferenceType: selectedPreference,
      sensitiveAutoEscalate: sensitiveEscalate,
    });
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "received":
        return <Badge variant="secondary" className="gap-1"><Package className="h-3 w-3" />Received</Badge>;
      case "pending_approval":
        return <Badge variant="outline" className="gap-1 border-yellow-500 text-yellow-600"><Clock className="h-3 w-3" />Pending Approval</Badge>;
      case "approved_scan":
        return <Badge variant="secondary" className="gap-1"><Eye className="h-3 w-3" />To Scan</Badge>;
      case "scanned":
        return <Badge className="gap-1 bg-primary"><CheckCircle2 className="h-3 w-3" />Scanned</Badge>;
      case "forwarded":
        return <Badge variant="secondary" className="gap-1"><Forward className="h-3 w-3" />Forwarded</Badge>;
      case "discarded":
        return <Badge variant="destructive" className="gap-1"><Trash2 className="h-3 w-3" />Discarded</Badge>;
      default:
        return <Badge variant="secondary">{status}</Badge>;
    }
  };

  if (isLoading) {
    return (
      <DashboardLayout
        role="founder"
        breadcrumbs={[
          { label: "Dashboard", href: "/founder/dashboard" },
          { label: "Mail Handling" },
        ]}
      >
        <div className="flex items-center justify-center h-64">
          <LoadingSpinner size="lg" />
        </div>
      </DashboardLayout>
    );
  }

  if (!hasMailService) {
    return (
      <DashboardLayout
        role="founder"
        breadcrumbs={[
          { label: "Dashboard", href: "/founder/dashboard" },
          { label: "Mail Handling" },
        ]}
      >
        <div className="max-w-2xl mx-auto">
          <EmptyState
            icon={Mail}
            title="Mail Handling Not Available"
            description="Mail handling requires an active Office + Mail subscription."
            action={
              <Link href="/founder/registered-office">
                <Button className="gap-2" data-testid="link-upgrade-subscription">
                  <Building2 className="h-4 w-4" />
                  Upgrade Subscription
                </Button>
              </Link>
            }
          />
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout
      role="founder"
      breadcrumbs={[
        { label: "Dashboard", href: "/founder/dashboard" },
        { label: "Mail Handling" },
      ]}
    >
      <div className="max-w-4xl mx-auto space-y-6">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Mail className="h-6 w-6 text-primary" />
            Mail Handling
          </h1>
          <p className="text-muted-foreground mt-1">
            Manage how mail to your registered office is processed
          </p>
        </div>

        {servicePolicy && (
          <Card className="border-blue-200 dark:border-blue-800 bg-blue-50 dark:bg-blue-950/30">
            <CardHeader className="pb-2">
              <CardTitle className="flex items-center gap-2 text-lg">
                <Info className="h-5 w-5 text-blue-600" />
                Service Policy
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 text-sm">
                <div className="flex items-start gap-2">
                  <Package className="h-4 w-4 text-blue-600 mt-0.5" />
                  <div>
                    <p className="font-medium">{servicePolicy.mailItemsIncluded} items/month</p>
                    <p className="text-muted-foreground text-xs">Included in plan</p>
                  </div>
                </div>
                <div className="flex items-start gap-2">
                  <Calendar className="h-4 w-4 text-blue-600 mt-0.5" />
                  <div>
                    <p className="font-medium">{servicePolicy.storageRetentionDays} days retention</p>
                    <p className="text-muted-foreground text-xs">Mail storage period</p>
                  </div>
                </div>
                <div className="flex items-start gap-2">
                  <FileCheck className="h-4 w-4 text-blue-600 mt-0.5" />
                  <div>
                    <p className="font-medium">{servicePolicy.officialMailOnly ? "Official mail only" : "All mail accepted"}</p>
                    <p className="text-muted-foreground text-xs">Government, bank, legal, commercial</p>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        <div className="grid gap-6 lg:grid-cols-2">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Settings className="h-5 w-5 text-primary" />
                Mail Preferences
              </CardTitle>
              <CardDescription>
                Choose how incoming mail should be handled
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              <RadioGroup
                value={selectedPreference}
                onValueChange={setSelectedPreference}
                className="space-y-3"
              >
                {preferenceOptions.map((option) => (
                  <div
                    key={option.value}
                    className={`flex items-start gap-3 border rounded-lg p-4 cursor-pointer hover-elevate ${
                      selectedPreference === option.value ? "border-primary bg-primary/5" : ""
                    }`}
                    onClick={() => setSelectedPreference(option.value)}
                  >
                    <RadioGroupItem value={option.value} id={`pref-${option.value}`} data-testid={`radio-pref-${option.value}`} />
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <option.icon className="h-4 w-4 text-primary" />
                        <Label htmlFor={`pref-${option.value}`} className="font-medium cursor-pointer">
                          {option.title}
                        </Label>
                      </div>
                      <p className="text-sm text-muted-foreground mt-1">{option.description}</p>
                    </div>
                  </div>
                ))}
              </RadioGroup>

              <div className="flex items-center justify-between border rounded-lg p-4">
                <div className="flex items-start gap-3">
                  <Shield className="h-5 w-5 text-amber-600 mt-0.5" />
                  <div>
                    <Label className="font-medium">Sensitive Mail Escalation</Label>
                    <p className="text-sm text-muted-foreground">
                      Automatically escalate mail marked as sensitive (legal notices, court documents)
                    </p>
                  </div>
                </div>
                <Switch
                  checked={sensitiveEscalate}
                  onCheckedChange={setSensitiveEscalate}
                  data-testid="switch-sensitive-escalate"
                />
              </div>

              <Button
                onClick={handleSavePreferences}
                disabled={!selectedPreference || updatePreferenceMutation.isPending}
                className="w-full"
                data-testid="button-save-preferences"
              >
                {updatePreferenceMutation.isPending ? (
                  <LoadingSpinner size="sm" />
                ) : (
                  "Save Preferences"
                )}
              </Button>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Inbox className="h-5 w-5 text-primary" />
                Mail Inbox
                {(mailData?.pendingApprovals ?? 0) > 0 && (
                  <Badge variant="destructive">{mailData?.pendingApprovals} pending</Badge>
                )}
              </CardTitle>
              <CardDescription>
                Recent mail received at your registered office
              </CardDescription>
            </CardHeader>
            <CardContent>
              {!mailData?.mailItems?.length ? (
                <div className="text-center py-8 text-muted-foreground">
                  <Mail className="h-12 w-12 mx-auto mb-4 opacity-50" />
                  <p>No mail items yet</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {mailData.mailItems.slice(0, 10).map((item) => (
                    <div
                      key={item.id}
                      className="flex items-start justify-between border rounded-lg p-3 hover-elevate"
                      data-testid={`mail-item-${item.id}`}
                    >
                      <div className="flex items-start gap-3">
                        {item.itemType === "letter" ? (
                          <FileText className="h-5 w-5 text-muted-foreground mt-0.5" />
                        ) : (
                          <Package className="h-5 w-5 text-muted-foreground mt-0.5" />
                        )}
                        <div>
                          <p className="font-medium text-sm">{item.senderLabel || "Unknown Sender"}</p>
                          <p className="text-xs text-muted-foreground">
                            {new Date(item.receivedAt).toLocaleDateString()}
                          </p>
                          <div className="mt-1">{getStatusBadge(item.status)}</div>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        {item.status === "pending_approval" && (
                          <>
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => approvalMutation.mutate({ itemId: item.id, action: "scan" })}
                              disabled={approvalMutation.isPending}
                              data-testid={`button-approve-scan-${item.id}`}
                            >
                              <Eye className="h-4 w-4" />
                            </Button>
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => approvalMutation.mutate({ itemId: item.id, action: "forward" })}
                              disabled={approvalMutation.isPending}
                              data-testid={`button-approve-forward-${item.id}`}
                            >
                              <Forward className="h-4 w-4" />
                            </Button>
                            <Button
                              size="sm"
                              variant="ghost"
                              onClick={() => approvalMutation.mutate({ itemId: item.id, action: "discard" })}
                              disabled={approvalMutation.isPending}
                              data-testid={`button-discard-${item.id}`}
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </>
                        )}
                        {item.scannedFileUrl && (
                          <Button
                            size="sm"
                            variant="outline"
                            asChild
                            data-testid={`button-view-scan-${item.id}`}
                          >
                            <a href={item.scannedFileUrl} target="_blank" rel="noopener noreferrer">
                              <ExternalLink className="h-4 w-4" />
                            </a>
                          </Button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </DashboardLayout>
  );
}

server/services/paystackWebhookHandler.t.content:
import { storage } from '../storage';
import { db } from '../db';
import { orderPayments, orders, orderItems, serviceRequests, companyApplications, users } from '@shared/schema';
import { eq, and } from 'drizzle-orm';
import { verifyWebhookSignature, verifyTransaction } from './paystackPaymentService';
import type { ServiceType, RegisteredOfficeTier } from '../config/priceBook';

export interface PaystackWebhookEvent {
  event: string;
  data: {
    id: number;
    domain: string;
    status: string;
    reference: string;
    amount: number;
    message?: string;
    gateway_response: string;
    paid_at?: string;
    created_at: string;
    channel: string;
    currency: string;
    ip_address?: string;
    metadata?: {
      userId?: string;
      founderId?: string;
      orderId?: number;
      applicationId?: number;
      subscriptionId?: number;
      items?: string[];
      lineItems?: Array<{
        serviceType: ServiceType;
        tier?: RegisteredOfficeTier;
        amount: number;
        description: string;
      }>;
    };
    customer: {
      id: number;
      first_name?: string;
      last_name?: string;
      email: string;
      customer_code: string;
      phone?: string;
    };
    authorization?: {
      authorization_code: string;
      bin: string;
      last4: string;
      exp_month: string;
      exp_year: string;
      channel: string;
      card_type: string;
      bank: string;
      country_code: string;
      brand: string;
      reusable: boolean;
      signature: string;
    };
  };
}

export async function processWebhook(
  payload: string,
  signature: string
): Promise<{ processed: boolean; event?: string; error?: string }> {
  if (!verifyWebhookSignature(payload, signature)) {
    console.error('[Paystack Webhook] Invalid signature');
    return { processed: false, error: 'Invalid signature' };
  }

  let event: PaystackWebhookEvent;
  try {
    event = JSON.parse(payload);
  } catch (e) {
    console.error('[Paystack Webhook] Invalid JSON payload');
    return { processed: false, error: 'Invalid JSON' };
  }

  console.log(`[Paystack Webhook] Received event: ${event.event}`);

  switch (event.event) {
    case 'charge.success':
      await handleChargeSuccess(event.data, payload);
      break;
    case 'charge.failed':
      await handleChargeFailed(event.data, payload);
      break;
    default:
      console.log(`[Paystack Webhook] Unhandled event type: ${event.event}`);
  }

  return { processed: true, event: event.event };
}

async function handleChargeSuccess(data: PaystackWebhookEvent['data'], rawPayload: string): Promise<void> {
  const reference = data.reference;

  const isSplitOrder = reference.startsWith('celion_split_');

  if (isSplitOrder) {
    await handleSplitOrderSuccess(data, rawPayload);
  } else {
    await handleLegacyPaymentSuccess(data);
  }
}

async function handleSplitOrderSuccess(data: PaystackWebhookEvent['data'], rawPayload: string): Promise<void> {
  const reference = data.reference;

  const [payment] = await db.select().from(orderPayments)
    .where(eq(orderPayments.paystackReference, reference));

  if (!payment) {
    console.error(`[Paystack Webhook] No order payment found for reference: ${reference}`);
    return;
  }

  if (payment.status === 'paid') {
    console.log(`[Paystack Webhook] Payment already processed for reference: ${reference}`);
    return;
  }

  const verification = await verifyTransaction(reference);
  if (verification.status !== 'success') {
    console.error(`[Paystack Webhook] Verification failed for reference: ${reference}`);
    return;
  }

  if (verification.amount !== payment.amount) {
    console.error(`[Paystack Webhook] Amount mismatch: expected ${payment.amount}, got ${verification.amount} for reference: ${reference}`);
    return;
  }

  if (verification.currency !== 'NGN') {
    console.error(`[Paystack Webhook] Currency mismatch: expected NGN, got ${verification.currency} for reference: ${reference}`);
    return;
  }

  await db.update(orderPayments)
    .set({
      status: 'paid',
      paidAt: data.paid_at ? new Date(data.paid_at) : new Date(),
      rawEvent: JSON.parse(rawPayload),
      updatedAt: new Date(),
    })
    .where(eq(orderPayments.id, payment.id));

  const [order] = await db.select().from(orders)
    .where(eq(orders.id, payment.orderId));

  if (!order) {
    console.error(`[Paystack Webhook] No order found for orderId: ${payment.orderId}`);
    return;
  }

  await db.update(orders)
    .set({ status: 'paid', updatedAt: new Date() })
    .where(eq(orders.id, order.id));

  const items = await db.select().from(orderItems)
    .where(eq(orderItems.orderId, order.id));

  if (order.applicationId) {
    try {
      await storage.updateApplication(order.applicationId, {
        paymentState: 'paid_escrowed',
        paymentStateUpdatedAt: new Date(),
      });

      await storage.createAuditLog({
        actorUserId: order.founderId,
        action: 'incorporation_fee_paid_split',
        entityType: 'company_application',
        entityId: String(order.applicationId),
        details: {
          provider: 'paystack',
          orderId: order.id,
          paymentState: 'paid_escrowed',
          totalAmount: order.totalAmount,
          cellionCut: order.totalCellionCut,
          lawyerNet: order.totalLawyerNet,
        },
      });
    } catch (err) {
      console.error(`[Paystack Webhook] Error updating application ${order.applicationId}:`, err);
    }
  }

  for (const item of items) {
    const serviceType = item.sku;
    if (['SCUML', 'TM', 'TIN'].includes(serviceType)) {
      try {
        await db.insert(serviceRequests).values({
          founderId: order.founderId,
          orderId: order.id,
          orderItemId: item.id,
          serviceType,
          status: 'queued',
          notes: `Auto-created from paid order #${order.id}`,
        });

        await storage.createAuditLog({
          actorUserId: order.founderId,
          action: 'service_request_created',
          entityType: 'service_request',
          entityId: `${serviceType}_order_${order.id}`,
          details: { serviceType, orderId: order.id, sku: item.sku },
        });
      } catch (err) {
        console.error(`[Paystack Webhook] Error creating service request for ${serviceType}:`, err);
      }
    }

    if (serviceType === 'VERIFY') {
      try {
        await db.update(users)
          .set({ isIdentityVerified: true, identityVerifiedAt: new Date(), updatedAt: new Date() })
          .where(eq(users.id, order.founderId));

        await storage.createAuditLog({
          actorUserId: order.founderId,
          action: 'identity_verification_activated',
          entityType: 'user',
          entityId: order.founderId,
          details: { orderId: order.id, method: 'payment', sku: 'VERIFY' },
        });

        console.log(`[Paystack Webhook] User ${order.founderId} marked as identity verified`);
      } catch (err) {
        console.error(`[Paystack Webhook] Error marking user as verified:`, err);
      }
    }
  }

  await storage.createAuditLog({
    actorUserId: order.founderId,
    action: 'split_payment_completed',
    entityType: 'order',
    entityId: String(order.id),
    details: {
      reference,
      amount: data.amount,
      currency: data.currency,
      channel: data.channel,
      totalAmount: order.totalAmount,
      cellionCut: order.totalCellionCut,
      lawyerNet: order.totalLawyerNet,
      items: items.map(i => ({ sku: i.sku, unitPrice: i.unitPrice, cellionCut: i.cellionCut, lawyerNet: i.lawyerNet })),
    },
  });

  await storage.createAuditLog({
    actorUserId: order.founderId,
    action: 'payout_split_recorded',
    entityType: 'order',
    entityId: String(order.id),
    details: {
      cellionCut: order.totalCellionCut,
      lawyerNet: order.totalLawyerNet,
      subaccountSettlement: true,
    },
  });

  await storage.createNotification({
    userId: order.founderId,
    title: 'Payment Successful',
    message: `Your payment of ₦${(order.totalAmount / 100).toLocaleString()} has been processed successfully.`,
    type: 'success',
    linkUrl: `/founder/orders/${order.id}`,
  });

  console.log(`[Paystack Webhook] Split payment processed for order #${order.id}, reference: ${reference}`);
}

async function handleLegacyPaymentSuccess(data: PaystackWebhookEvent['data']): Promise<void> {
  const reference = data.reference;

  const transaction = await storage.getPaystackTransactionByReference(reference);
  if (!transaction) {
    console.error(`[Paystack Webhook] No transaction found for reference: ${reference}`);
    return;
  }

  const verification = await verifyTransaction(reference);
  if (verification.status !== 'success') {
    console.error(`[Paystack Webhook] Verification failed for reference: ${reference}`);
    return;
  }

  await storage.updatePaystackTransaction(transaction.id, {
    status: 'success',
    paystackTransactionId: String(data.id),
    gatewayResponse: data.gateway_response,
    channel: data.channel,
    completedAt: data.paid_at ? new Date(data.paid_at) : new Date(),
  });

  const lineItems = transaction.lineItems || [];
  const context = transaction.contextJson || {};
  const userId = transaction.userId;

  for (const item of lineItems) {
    await activateService(
      userId,
      item.serviceType as ServiceType,
      item.tier as RegisteredOfficeTier | undefined,
      context
    );
  }

  await storage.createAuditLog({
    actorUserId: userId,
    action: 'paystack_payment_completed',
    entityType: 'paystack_transaction',
    entityId: String(transaction.id),
    details: {
      reference,
      amount: data.amount,
      currency: data.currency,
      channel: data.channel,
      lineItems: lineItems.map(i => ({ serviceType: i.serviceType, tier: i.tier })),
    },
  });

  await storage.createNotification({
    userId,
    title: 'Payment Successful',
    message: `Your payment of ₦${((transaction.amountTotal || 0) / 100).toLocaleString()} has been processed successfully.`,
    type: 'success',
    linkUrl: '/founder/dashboard',
  });

  console.log(`[Paystack Webhook] Legacy payment processed for reference: ${reference}`);
}

async function handleChargeFailed(data: PaystackWebhookEvent['data'], rawPayload: string): Promise<void> {
  const reference = data.reference;
  const isSplitOrder = reference.startsWith('celion_split_');

  if (isSplitOrder) {
    const [payment] = await db.select().from(orderPayments)
      .where(eq(orderPayments.paystackReference, reference));

    if (payment) {
      await db.update(orderPayments)
        .set({ status: 'failed', rawEvent: JSON.parse(rawPayload), updatedAt: new Date() })
        .where(eq(orderPayments.id, payment.id));

      await db.update(orders)
        .set({ status: 'failed', updatedAt: new Date() })
        .where(eq(orders.id, payment.orderId));

      const [order] = await db.select().from(orders).where(eq(orders.id, payment.orderId));
      if (order) {
        await storage.createNotification({
          userId: order.founderId,
          title: 'Payment Failed',
          message: `Your payment of ₦${(order.totalAmount / 100).toLocaleString()} could not be processed. ${data.gateway_response || 'Please try again.'}`,
          type: 'warning',
          linkUrl: '/payment/checkout',
        });

        await storage.createAuditLog({
          actorUserId: order.founderId,
          action: 'split_payment_failed',
          entityType: 'order',
          entityId: String(order.id),
          details: { reference, gatewayResponse: data.gateway_response },
        });
      }
    }
  } else {
    const transaction = await storage.getPaystackTransactionByReference(reference);
    if (transaction) {
      await storage.updatePaystackTransaction(transaction.id, {
        status: 'failed',
        paystackTransactionId: String(data.id),
        gatewayResponse: data.gateway_response,
      });

      await storage.createNotification({
        userId: transaction.userId,
        title: 'Payment Failed',
        message: `Your payment of ₦${((transaction.amountTotal || 0) / 100).toLocaleString()} could not be processed. ${data.gateway_response || 'Please try again.'}`,
        type: 'warning',
        linkUrl: '/payment/checkout',
      });
    }
  }

  console.log(`[Paystack Webhook] Payment failed for reference: ${reference}`);
}

async function activateService(
  userId: string,
  serviceType: ServiceType,
  tier: RegisteredOfficeTier | undefined,
  context: { applicationId?: number; subscriptionId?: number }
): Promise<void> {
  switch (serviceType) {
    case 'verification': {
      const verification = await storage.getIdentityVerification(userId);
      if (verification) {
        await storage.upsertIdentityVerification({
          founderUserId: userId,
          status: verification.status === 'not_started' ? 'pending' : verification.status,
          notes: `${verification.notes || ''}\nVerification fee paid via Paystack.`.trim(),
        });
      } else {
        await storage.upsertIdentityVerification({
          founderUserId: userId,
          status: 'pending',
          notes: 'Verification fee paid via Paystack.',
        });
      }

      await storage.createAuditLog({
        actorUserId: userId,
        action: 'verification_fee_paid',
        entityType: 'identity_verification',
        entityId: userId,
        details: { provider: 'paystack' },
      });
      break;
    }

    case 'incorporation': {
      if (context.applicationId) {
        const application = await storage.getApplication(context.applicationId);
        if (application && application.founderUserId === userId) {
          await storage.updateApplication(context.applicationId, {
            paymentState: 'paid_escrowed',
            paymentStateUpdatedAt: new Date(),
          });

          await storage.createAuditLog({
            actorUserId: userId,
            action: 'incorporation_fee_paid',
            entityType: 'company_application',
            entityId: String(context.applicationId),
            details: { provider: 'paystack', paymentState: 'paid_escrowed' },
          });
        }
      }
      break;
    }

    case 'registered_office': {
      if (context.subscriptionId) {
        const now = new Date();
        const oneYearFromNow = new Date(now);
        oneYearFromNow.setFullYear(oneYearFromNow.getFullYear() + 1);

        await storage.updateRegisteredOfficeSubscription(context.subscriptionId, {
          status: 'active',
          startDate: now,
          endDate: oneYearFromNow,
        });

        await storage.createAuditLog({
          actorUserId: userId,
          action: 'registered_office_activated_paid',
          entityType: 'registered_office_subscription',
          entityId: String(context.subscriptionId),
          details: {
            provider: 'paystack',
            tier,
            startDate: now.toISOString(),
            endDate: oneYearFromNow.toISOString(),
          },
        });

        await storage.createNotification({
          userId,
          title: 'Registered Office Activated',
          message: `Your registered office subscription (${tier === 'office_plus_mail' ? 'Office + Mail' : 'Office Only'}) is now active until ${oneYearFromNow.toLocaleDateString()}.`,
          type: 'success',
          linkUrl: '/founder/registered-office',
        });
      }
      break;
    }
  }
}

export default {
  processWebhook,
};

