import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { DashboardLayout } from "@/components/dashboard-layout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Separator } from "@/components/ui/separator";
import { LoadingSpinner } from "@/components/loading-spinner";
import { EmptyState } from "@/components/empty-state";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import {
  Building2,
  ChevronLeft,
  Users,
  MapPin,
  Briefcase,
  Hash,
  Calendar,
  FileText,
  Pencil,
  Check,
  X,
  PieChart,
  ClipboardList,
} from "lucide-react";
import type { CompanyProfile, PostIncorporationTask } from "@shared/schema";
import { Link } from "wouter";

interface ProfileWithTasks extends CompanyProfile {
  tasks?: PostIncorporationTask[];
}

export default function CompanyProfilePage() {
  const [selectedProfileId, setSelectedProfileId] = useState<number | null>(null);
  const { toast } = useToast();

  const { data: profiles, isLoading: profilesLoading } = useQuery<CompanyProfile[]>({
    queryKey: ["/api/founder/company-profiles"],
  });

  const { data: profileDetail, isLoading: detailLoading } = useQuery<ProfileWithTasks>({
    queryKey: ["/api/founder/company-profiles", selectedProfileId],
    enabled: !!selectedProfileId,
  });

  if (selectedProfileId) {
    return (
      <DashboardLayout role="founder" breadcrumbs={[
        { label: "Company Profiles", href: "/founder/company-profile" },
        { label: profileDetail?.companyName || "Loading..." },
      ]}>
        <ProfileDetailView
          profile={profileDetail}
          isLoading={detailLoading}
          onBack={() => setSelectedProfileId(null)}
          toast={toast}
        />
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout role="founder" breadcrumbs={[{ label: "Company Profiles" }]}>
      <div className="space-y-6" data-testid="company-profiles-page">
        <div className="flex items-center justify-between gap-2 flex-wrap">
          <div>
            <h1 className="text-2xl font-semibold" data-testid="text-page-title">Company Profiles</h1>
            <p className="text-sm text-muted-foreground mt-1">
              View and manage your incorporated companies
            </p>
          </div>
        </div>

        {profilesLoading ? (
          <div className="flex justify-center py-12">
            <LoadingSpinner size="lg" />
          </div>
        ) : !profiles?.length ? (
          <EmptyState
            icon={Building2}
            title="No company profiles yet"
            description="Company profiles are automatically created when your incorporation application is completed or filed. Check your applications for status."
          />
        ) : (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {profiles.map((profile) => (
              <Card
                key={profile.id}
                className="cursor-pointer hover-elevate transition-colors"
                onClick={() => setSelectedProfileId(profile.id)}
                data-testid={`card-company-profile-${profile.id}`}
              >
                <CardHeader className="flex flex-row items-start justify-between gap-2 pb-3">
                  <div className="space-y-1 min-w-0">
                    <CardTitle className="text-base truncate" data-testid={`text-company-name-${profile.id}`}>
                      {profile.companyName}
                    </CardTitle>
                    <Badge variant="secondary" data-testid={`badge-company-type-${profile.id}`}>
                      {profile.companyType || "LTD"}
                    </Badge>
                  </div>
                  <Building2 className="h-5 w-5 text-muted-foreground shrink-0" />
                </CardHeader>
                <CardContent className="space-y-2">
                  {profile.rcNumber && (
                    <div className="flex items-center gap-2 text-sm">
                      <Hash className="h-3.5 w-3.5 text-muted-foreground" />
                      <span className="text-muted-foreground">RC:</span>
                      <span data-testid={`text-rc-number-${profile.id}`}>{profile.rcNumber}</span>
                    </div>
                  )}
                  {profile.incorporationDate && (
                    <div className="flex items-center gap-2 text-sm">
                      <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
                      <span className="text-muted-foreground">Incorporated:</span>
                      <span data-testid={`text-inc-date-${profile.id}`}>
                        {new Date(profile.incorporationDate).toLocaleDateString()}
                      </span>
                    </div>
                  )}
                  {!profile.rcNumber && !profile.incorporationDate && (
                    <p className="text-sm text-muted-foreground">
                      Pending incorporation details
                    </p>
                  )}
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

function ProfileDetailView({
  profile,
  isLoading,
  onBack,
  toast,
}: {
  profile: ProfileWithTasks | undefined;
  isLoading: boolean;
  onBack: () => void;
  toast: ReturnType<typeof useToast>["toast"];
}) {
  const [editingField, setEditingField] = useState<string | null>(null);
  const [editValue, setEditValue] = useState("");

  const updateMutation = useMutation({
    mutationFn: async (data: Record<string, any>) => {
      const res = await apiRequest("PUT", `/api/founder/company-profiles/${profile?.id}`, data);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/founder/company-profiles", profile?.id] });
      queryClient.invalidateQueries({ queryKey: ["/api/founder/company-profiles"] });
      setEditingField(null);
      toast({ title: "Updated", description: "Company profile updated successfully." });
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const handleSave = (field: string) => {
    updateMutation.mutate({ [field]: editValue });
  };

  const startEditing = (field: string, currentValue: string) => {
    setEditingField(field);
    setEditValue(currentValue || "");
  };

  if (isLoading) {
    return (
      <div className="flex justify-center py-12">
        <LoadingSpinner size="lg" />
      </div>
    );
  }

  if (!profile) {
    return (
      <EmptyState
        icon={Building2}
        title="Profile not found"
        description="The company profile could not be loaded."
      />
    );
  }

  const address = profile.registeredAddress as any;
  const directors = (profile.directors || []) as { name: string; role?: string; email?: string }[];
  const shareholders = (profile.shareholders || []) as { name: string; shares?: number; percentage?: number }[];
  const activities = (profile.businessActivities || []) as string[];
  const completedTasks = profile.tasks?.filter(t => t.status === "completed").length || 0;
  const totalTasks = profile.tasks?.length || 0;

  return (
    <div className="space-y-6" data-testid="company-profile-detail">
      <div className="flex items-center gap-3 flex-wrap">
        <Button variant="ghost" size="icon" onClick={onBack} data-testid="button-back">
          <ChevronLeft className="h-4 w-4" />
        </Button>
        <div className="min-w-0">
          <h1 className="text-2xl font-semibold truncate" data-testid="text-detail-company-name">
            {profile.companyName}
          </h1>
          <div className="flex items-center gap-2 mt-1 flex-wrap">
            <Badge variant="secondary" data-testid="badge-detail-company-type">
              {profile.companyType || "LTD"}
            </Badge>
            {profile.rcNumber && (
              <Badge variant="outline" data-testid="badge-detail-rc">RC {profile.rcNumber}</Badge>
            )}
          </div>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
        <Card data-testid="card-company-details">
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Building2 className="h-4 w-4" />
              Company Details
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <EditableField
              label="RC Number"
              value={profile.rcNumber || ""}
              field="rcNumber"
              editingField={editingField}
              editValue={editValue}
              isPending={updateMutation.isPending}
              onStartEdit={startEditing}
              onSave={handleSave}
              onCancel={() => setEditingField(null)}
              onEditValueChange={setEditValue}
              placeholder="Enter RC number"
              testIdPrefix="rc-number"
            />

            <div className="space-y-1">
              <label className="text-sm text-muted-foreground">Incorporation Date</label>
              <p className="text-sm" data-testid="text-detail-inc-date">
                {profile.incorporationDate
                  ? new Date(profile.incorporationDate).toLocaleDateString()
                  : "Not set"}
              </p>
            </div>

            <EditableField
              label="TIN Number"
              value={profile.tinNumber || ""}
              field="tinNumber"
              editingField={editingField}
              editValue={editValue}
              isPending={updateMutation.isPending}
              onStartEdit={startEditing}
              onSave={handleSave}
              onCancel={() => setEditingField(null)}
              onEditValueChange={setEditValue}
              placeholder="Enter TIN number"
              testIdPrefix="tin-number"
            />

            {profile.shareCapital && (
              <div className="space-y-1">
                <label className="text-sm text-muted-foreground">Share Capital</label>
                <p className="text-sm" data-testid="text-share-capital">{profile.shareCapital}</p>
              </div>
            )}
          </CardContent>
        </Card>

        <Card data-testid="card-registered-address">
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <MapPin className="h-4 w-4" />
              Registered Address
            </CardTitle>
          </CardHeader>
          <CardContent>
            {address ? (
              <div className="text-sm space-y-1" data-testid="text-address">
                {address.line1 && <p>{address.line1}</p>}
                {address.line2 && <p>{address.line2}</p>}
                <p>
                  {[address.city, address.state, address.postalCode].filter(Boolean).join(", ")}
                </p>
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">No address on file</p>
            )}
          </CardContent>
        </Card>

        <Card data-testid="card-directors">
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Users className="h-4 w-4" />
              Directors ({directors.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {directors.length > 0 ? (
              <div className="space-y-3">
                {directors.map((d, i) => (
                  <div key={i} className="flex items-center justify-between gap-2" data-testid={`row-director-${i}`}>
                    <div>
                      <p className="text-sm font-medium" data-testid={`text-director-name-${i}`}>{d.name}</p>
                      {d.email && <p className="text-xs text-muted-foreground">{d.email}</p>}
                    </div>
                    {d.role && (
                      <Badge variant="outline" className="shrink-0" data-testid={`badge-director-role-${i}`}>
                        {d.role}
                      </Badge>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">No directors listed</p>
            )}
          </CardContent>
        </Card>

        <Card data-testid="card-shareholders">
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <PieChart className="h-4 w-4" />
              Shareholders ({shareholders.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {shareholders.length > 0 ? (
              <div className="space-y-3">
                {shareholders.map((s, i) => (
                  <div key={i} className="flex items-center justify-between gap-2" data-testid={`row-shareholder-${i}`}>
                    <p className="text-sm font-medium" data-testid={`text-shareholder-name-${i}`}>{s.name}</p>
                    <div className="flex items-center gap-2 shrink-0">
                      {s.percentage !== undefined && s.percentage !== null && (
                        <Badge variant="secondary" data-testid={`badge-shareholder-pct-${i}`}>
                          {s.percentage}%
                        </Badge>
                      )}
                      {s.shares !== undefined && s.shares !== null && (
                        <span className="text-xs text-muted-foreground">
                          {s.shares.toLocaleString()} shares
                        </span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">No shareholders listed</p>
            )}
          </CardContent>
        </Card>

        <Card className="lg:col-span-2" data-testid="card-business-activities">
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Briefcase className="h-4 w-4" />
              Business Activities ({activities.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {activities.length > 0 ? (
              <div className="flex flex-wrap gap-2">
                {activities.map((a, i) => (
                  <Badge key={i} variant="outline" data-testid={`badge-activity-${i}`}>
                    {a}
                  </Badge>
                ))}
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">No business activities listed</p>
            )}
          </CardContent>
        </Card>
      </div>

      <Separator />

      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div className="flex items-center gap-3">
          <ClipboardList className="h-5 w-5 text-muted-foreground" />
          <div>
            <p className="text-sm font-medium">Post-Incorporation Checklist</p>
            <p className="text-xs text-muted-foreground">
              {completedTasks} of {totalTasks} tasks completed
            </p>
          </div>
        </div>
        <Link href={`/founder/post-inc-checklist?profileId=${profile.id}`}>
          <Button variant="outline" data-testid="button-view-checklist">
            View Checklist
          </Button>
        </Link>
      </div>

      <div className="flex items-center gap-3 flex-wrap">
        <Link href="/founder/vault">
          <Button variant="outline" data-testid="button-view-vault">
            <FileText className="h-4 w-4 mr-2" />
            View Documents in Vault
          </Button>
        </Link>
      </div>
    </div>
  );
}

function EditableField({
  label,
  value,
  field,
  editingField,
  editValue,
  isPending,
  onStartEdit,
  onSave,
  onCancel,
  onEditValueChange,
  placeholder,
  testIdPrefix,
}: {
  label: string;
  value: string;
  field: string;
  editingField: string | null;
  editValue: string;
  isPending: boolean;
  onStartEdit: (field: string, value: string) => void;
  onSave: (field: string) => void;
  onCancel: () => void;
  onEditValueChange: (value: string) => void;
  placeholder: string;
  testIdPrefix: string;
}) {
  const isEditing = editingField === field;

  return (
    <div className="space-y-1">
      <label className="text-sm text-muted-foreground">{label}</label>
      {isEditing ? (
        <div className="flex items-center gap-2">
          <Input
            value={editValue}
            onChange={(e) => onEditValueChange(e.target.value)}
            placeholder={placeholder}
            data-testid={`input-${testIdPrefix}`}
          />
          <Button
            size="icon"
            variant="ghost"
            onClick={() => onSave(field)}
            disabled={isPending}
            data-testid={`button-save-${testIdPrefix}`}
          >
            <Check className="h-4 w-4" />
          </Button>
          <Button
            size="icon"
            variant="ghost"
            onClick={onCancel}
            data-testid={`button-cancel-${testIdPrefix}`}
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
      ) : (
        <div className="flex items-center gap-2">
          <p className="text-sm" data-testid={`text-${testIdPrefix}`}>
            {value || "Not set"}
          </p>
          <Button
            size="icon"
            variant="ghost"
            onClick={() => onStartEdit(field, value)}
            data-testid={`button-edit-${testIdPrefix}`}
          >
            <Pencil className="h-3.5 w-3.5" />
          </Button>
        </div>
      )}
    </div>
  );
}

client/src/pages/founder/legal-assistant.content:
import { useState, useRef, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { DashboardLayout } from "@/components/dashboard-layout";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Textarea } from "@/components/ui/textarea";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/hooks/use-auth";
import { useToast } from "@/hooks/use-toast";
import { MessageSquare, Send, Plus, Trash2, Bot, User, Sparkles, PanelLeftClose, PanelLeft } from "lucide-react";
import type { LegalChatConversation, LegalChatMessage } from "@shared/schema";

const STARTER_QUESTIONS = [
  "What are the steps to incorporate a company in Nigeria?",
  "What documents do I need for CAC registration?",
  "What's the difference between LTD and PLC?",
  "What are my post-incorporation obligations?",
  "How do annual returns work for Nigerian companies?",
  "What are the penalties for late annual returns?",
];

export default function LegalAssistant() {
  const { user } = useAuth();
  const { toast } = useToast();
  const [selectedConversationId, setSelectedConversationId] = useState<number | null>(null);
  const [inputValue, setInputValue] = useState("");
  const [showSidebar, setShowSidebar] = useState(true);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const { data: conversations = [], isLoading: conversationsLoading } = useQuery<LegalChatConversation[]>({
    queryKey: ["/api/legal-chat/conversations"],
  });

  const { data: messages = [], isLoading: messagesLoading } = useQuery<LegalChatMessage[]>({
    queryKey: ["/api/legal-chat/conversations", selectedConversationId, "messages"],
    enabled: !!selectedConversationId,
  });

  const createConversation = useMutation({
    mutationFn: async () => {
      const res = await apiRequest("POST", "/api/legal-chat/conversations");
      return res.json();
    },
    onSuccess: (data: LegalChatConversation) => {
      queryClient.invalidateQueries({ queryKey: ["/api/legal-chat/conversations"] });
      setSelectedConversationId(data.id);
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const sendMessage = useMutation({
    mutationFn: async ({ conversationId, content }: { conversationId: number; content: string }) => {
      const res = await apiRequest("POST", `/api/legal-chat/conversations/${conversationId}/messages`, { content });
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/legal-chat/conversations", selectedConversationId, "messages"] });
      queryClient.invalidateQueries({ queryKey: ["/api/legal-chat/conversations"] });
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const deleteConversation = useMutation({
    mutationFn: async (id: number) => {
      await apiRequest("DELETE", `/api/legal-chat/conversations/${id}`);
    },
    onSuccess: (_, deletedId) => {
      queryClient.invalidateQueries({ queryKey: ["/api/legal-chat/conversations"] });
      if (selectedConversationId === deletedId) {
        setSelectedConversationId(null);
      }
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSend = async () => {
    if (!inputValue.trim() || sendMessage.isPending) return;

    let convId = selectedConversationId;
    if (!convId) {
      const newConv = await createConversation.mutateAsync();
      convId = newConv.id;
    }

    const content = inputValue.trim();
    setInputValue("");
    sendMessage.mutate({ conversationId: convId, content });
  };

  const handleStarterClick = async (question: string) => {
    setInputValue(question);
    let convId = selectedConversationId;
    if (!convId) {
      const newConv = await createConversation.mutateAsync();
      convId = newConv.id;
    }
    sendMessage.mutate({ conversationId: convId, content: question });
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const formatDate = (date: string | Date | null) => {
    if (!date) return "";
    return new Date(date).toLocaleDateString("en-NG", { month: "short", day: "numeric" });
  };

  return (
    <DashboardLayout role="founder" breadcrumbs={[{ label: "Legal AI Assistant" }]}>
      <div className="flex h-[calc(100vh-8rem)] gap-4">
        {showSidebar && (
          <Card className="w-72 shrink-0 flex flex-col overflow-hidden" data-testid="conversation-panel">
            <div className="p-3 border-b flex items-center justify-between gap-2">
              <h2 className="font-semibold text-sm">Conversations</h2>
              <div className="flex items-center gap-1">
                <Button
                  size="icon"
                  variant="ghost"
                  onClick={() => {
                    createConversation.mutate();
                  }}
                  disabled={createConversation.isPending}
                  data-testid="button-new-chat"
                >
                  <Plus className="h-4 w-4" />
                </Button>
                <Button
                  size="icon"
                  variant="ghost"
                  onClick={() => setShowSidebar(false)}
                  className="md:hidden"
                  data-testid="button-close-sidebar"
                >
                  <PanelLeftClose className="h-4 w-4" />
                </Button>
              </div>
            </div>
            <ScrollArea className="flex-1">
              <div className="p-2 space-y-1">
                {conversationsLoading ? (
                  <div className="p-4 text-center text-sm text-muted-foreground">Loading...</div>
                ) : conversations.length === 0 ? (
                  <div className="p-4 text-center text-sm text-muted-foreground">
                    No conversations yet
                  </div>
                ) : (
                  conversations.map((conv) => (
                    <div
                      key={conv.id}
                      className={`group flex items-center gap-2 rounded-md p-2 cursor-pointer hover-elevate ${
                        selectedConversationId === conv.id ? "bg-accent" : ""
                      }`}
                      onClick={() => setSelectedConversationId(conv.id)}
                      data-testid={`conversation-item-${conv.id}`}
                    >
                      <MessageSquare className="h-4 w-4 shrink-0 text-muted-foreground" />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm truncate">{conv.title || "New Conversation"}</p>
                        <p className="text-xs text-muted-foreground">{formatDate(conv.updatedAt)}</p>
                      </div>
                      <Button
                        size="icon"
                        variant="ghost"
                        className="h-7 w-7 opacity-0 group-hover:opacity-100 shrink-0"
                        onClick={(e) => {
                          e.stopPropagation();
                          deleteConversation.mutate(conv.id);
                        }}
                        data-testid={`button-delete-conversation-${conv.id}`}
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </Button>
                    </div>
                  ))
                )}
              </div>
            </ScrollArea>
          </Card>
        )}

        <div className="flex-1 flex flex-col min-w-0">
          {!showSidebar && (
            <div className="mb-2">
              <Button
                size="icon"
                variant="ghost"
                onClick={() => setShowSidebar(true)}
                data-testid="button-open-sidebar"
              >
                <PanelLeft className="h-4 w-4" />
              </Button>
            </div>
          )}

          <Card className="flex-1 flex flex-col overflow-hidden">
            <div className="p-3 border-b flex items-center gap-2">
              <Bot className="h-5 w-5 text-primary" />
              <div>
                <h2 className="font-semibold text-sm">Celion Legal AI</h2>
                <p className="text-xs text-muted-foreground">Nigerian Corporate Law Assistant</p>
              </div>
            </div>

            <ScrollArea className="flex-1 p-4">
              <div className="space-y-4 max-w-3xl mx-auto">
                {!selectedConversationId || (messages.length === 0 && !messagesLoading) ? (
                  <div className="flex flex-col items-center justify-center py-12 space-y-6">
                    <div className="h-16 w-16 rounded-full bg-primary/10 flex items-center justify-center">
                      <Sparkles className="h-8 w-8 text-primary" />
                    </div>
                    <div className="text-center space-y-2">
                      <h3 className="text-lg font-semibold">Ask Celion Legal AI</h3>
                      <p className="text-sm text-muted-foreground max-w-md">
                        Get guidance on Nigerian company incorporation, CAC procedures, and compliance requirements.
                      </p>
                    </div>
                    <div className="grid gap-2 sm:grid-cols-2 w-full max-w-lg">
                      {STARTER_QUESTIONS.map((question) => (
                        <Button
                          key={question}
                          variant="outline"
                          className="text-left h-auto whitespace-normal text-sm justify-start"
                          onClick={() => handleStarterClick(question)}
                          disabled={sendMessage.isPending || createConversation.isPending}
                          data-testid={`starter-question-${question.substring(0, 20).replace(/\s+/g, "-").toLowerCase()}`}
                        >
                          {question}
                        </Button>
                      ))}
                    </div>
                  </div>
                ) : (
                  <>
                    {messagesLoading ? (
                      <div className="flex justify-center py-8">
                        <div className="text-sm text-muted-foreground">Loading messages...</div>
                      </div>
                    ) : (
                      messages.map((msg) => (
                        <div
                          key={msg.id}
                          className={`flex gap-3 ${msg.role === "user" ? "flex-row-reverse" : ""}`}
                          data-testid={`message-${msg.id}`}
                        >
                          <Avatar className="h-8 w-8 shrink-0">
                            <AvatarFallback className={msg.role === "user" ? "bg-primary text-primary-foreground" : "bg-muted"}>
                              {msg.role === "user" ? <User className="h-4 w-4" /> : <Bot className="h-4 w-4" />}
                            </AvatarFallback>
                          </Avatar>
                          <div
                            className={`rounded-lg px-4 py-2.5 max-w-[80%] text-sm ${
                              msg.role === "user"
                                ? "bg-primary text-primary-foreground"
                                : "bg-muted"
                            }`}
                          >
                            <div className="whitespace-pre-wrap">{msg.content}</div>
                          </div>
                        </div>
                      ))
                    )}
                    {sendMessage.isPending && (
                      <div className="flex gap-3" data-testid="ai-loading-indicator">
                        <Avatar className="h-8 w-8 shrink-0">
                          <AvatarFallback className="bg-muted">
                            <Bot className="h-4 w-4" />
                          </AvatarFallback>
                        </Avatar>
                        <div className="rounded-lg px-4 py-2.5 bg-muted">
                          <div className="flex items-center gap-2 text-sm text-muted-foreground">
                            <div className="flex gap-1">
                              <span className="animate-bounce" style={{ animationDelay: "0ms" }}>.</span>
                              <span className="animate-bounce" style={{ animationDelay: "150ms" }}>.</span>
                              <span className="animate-bounce" style={{ animationDelay: "300ms" }}>.</span>
                            </div>
                            Thinking...
                          </div>
                        </div>
                      </div>
                    )}
                    <div ref={messagesEndRef} />
                  </>
                )}
              </div>
            </ScrollArea>

            <div className="p-3 border-t">
              <div className="flex gap-2 max-w-3xl mx-auto">
                <Textarea
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder="Ask about Nigerian corporate law..."
                  className="resize-none min-h-[44px] max-h-32"
                  rows={1}
                  disabled={sendMessage.isPending}
                  data-testid="input-message"
                />
                <Button
                  size="icon"
                  onClick={handleSend}
                  disabled={!inputValue.trim() || sendMessage.isPending}
                  data-testid="button-send-message"
                >
                  <Send className="h-4 w-4" />
                </Button>
              </div>
              <p className="text-xs text-muted-foreground text-center mt-2">
                AI assistant for informational purposes only. Consult a qualified lawyer for legal advice.
              </p>
            </div>
          </Card>
        </div>
      </div>
    </DashboardLayout>
  );
}

