import { useQuery } from "@tanstack/react-query";
import { Link } from "wouter";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Loader2, CheckCircle2, Clock, XCircle, ArrowRight, ShoppingCart } from "lucide-react";

function formatNgn(kobo: number): string {
  return `\u20A6${(kobo / 100).toLocaleString("en-NG", { minimumFractionDigits: 0 })}`;
}

function getStatusBadge(status: string) {
  switch (status) {
    case "paid":
      return <Badge variant="default"><CheckCircle2 className="h-3 w-3 mr-1" /> Paid</Badge>;
    case "pending_payment":
      return <Badge variant="secondary"><Clock className="h-3 w-3 mr-1" /> Pending</Badge>;
    case "failed":
      return <Badge variant="destructive"><XCircle className="h-3 w-3 mr-1" /> Failed</Badge>;
    default:
      return <Badge variant="outline">{status}</Badge>;
  }
}

function getFulfilmentBadge(status: string | null) {
  switch (status) {
    case "completed":
      return <Badge variant="default"><CheckCircle2 className="h-3 w-3 mr-1" /> Fulfilled</Badge>;
    case "in_progress":
      return <Badge variant="secondary"><Clock className="h-3 w-3 mr-1" /> In Progress</Badge>;
    case "cancelled":
      return <Badge variant="destructive"><XCircle className="h-3 w-3 mr-1" /> Cancelled</Badge>;
    default:
      return null;
  }
}

interface Order {
  id: number;
  status: string;
  currency: string;
  totalAmount: number;
  fulfilmentStatus: string | null;
  createdAt: string;
}

export default function FounderOrdersPage() {
  const { data: orders, isLoading } = useQuery<Order[]>({
    queryKey: ["/api/founder/orders"],
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="p-6 max-w-4xl mx-auto space-y-6">
      <div>
        <h1 className="text-2xl font-bold" data-testid="text-orders-title">My Orders</h1>
        <p className="text-muted-foreground mt-1">View and track all your orders and service requests</p>
      </div>

      {!orders || orders.length === 0 ? (
        <Card>
          <CardContent className="p-8 text-center space-y-4">
            <ShoppingCart className="h-12 w-12 text-muted-foreground/30 mx-auto" />
            <div>
              <h3 className="font-medium">No orders yet</h3>
              <p className="text-sm text-muted-foreground mt-1">
                Your orders will appear here after you purchase services.
              </p>
            </div>
            <Link href="/founder/checkout">
              <Button data-testid="button-go-checkout">Browse Services</Button>
            </Link>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          {[...orders].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()).map((order) => (
            <Link key={order.id} href={`/founder/orders/${order.id}`}>
              <Card className="hover-elevate cursor-pointer" data-testid={`card-order-${order.id}`}>
                <CardContent className="p-4">
                  <div className="flex items-center justify-between gap-4 flex-wrap">
                    <div className="flex items-center gap-4 min-w-0">
                      <div>
                        <p className="font-medium" data-testid={`text-order-id-${order.id}`}>
                          Order #{order.id}
                        </p>
                        <p className="text-sm text-muted-foreground">
                          {new Date(order.createdAt).toLocaleDateString("en-NG", {
                            year: "numeric",
                            month: "short",
                            day: "numeric",
                          })}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-3 flex-wrap">
                      {getStatusBadge(order.status)}
                      {getFulfilmentBadge(order.fulfilmentStatus)}
                      <span className="font-semibold" data-testid={`text-order-total-${order.id}`}>
                        {formatNgn(order.totalAmount)}
                      </span>
                      <ArrowRight className="h-4 w-4 text-muted-foreground" />
                    </div>
                  </div>
                </CardContent>
              </Card>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}

client/src/pages/settings.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { DashboardLayout } from "@/components/dashboard-layout";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/use-auth";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { updateProfileSchema, changePasswordSchema } from "@shared/schema";
import type { UpdateProfileInput, ChangePasswordInput } from "@shared/schema";
import { User, Lock, Bell, Loader2, Check } from "lucide-react";

interface ProfileData {
  firstName: string;
  lastName: string;
  email: string;
  hasPassword: boolean;
}

interface NotificationPrefs {
  complianceReminders: boolean;
  serviceRequestUpdates: boolean;
  orderUpdates: boolean;
  incorporationUpdates: boolean;
  marketingEmails: boolean;
}

export default function SettingsPage() {
  const { user } = useAuth();
  const roles = user?.roles || [];
  const role = roles.includes("admin") ? "admin" as const : roles.includes("lawyer") ? "lawyer" as const : "founder" as const;
  const dashboardPath = `/${role}/dashboard`;

  return (
    <DashboardLayout
      role={role}
      breadcrumbs={[{ label: "Dashboard", href: dashboardPath }, { label: "Settings" }]}
    >
      <div className="max-w-2xl mx-auto space-y-6 p-4 overflow-y-auto h-full">
        <div>
          <h1 className="text-2xl font-bold" data-testid="text-settings-title">Settings</h1>
          <p className="text-muted-foreground">Manage your account, security, and notification preferences</p>
        </div>

        <ProfileSection />
        <Separator />
        <PasswordSection />
        <Separator />
        <NotificationSection roles={roles} />
      </div>
    </DashboardLayout>
  );
}

function ProfileSection() {
  const { toast } = useToast();

  const { data: profile, isLoading } = useQuery<ProfileData>({
    queryKey: ["/api/settings/profile"],
  });

  const form = useForm<UpdateProfileInput>({
    resolver: zodResolver(updateProfileSchema),
    defaultValues: {
      firstName: "",
      lastName: "",
    },
    values: profile ? { firstName: profile.firstName, lastName: profile.lastName } : undefined,
  });

  const updateMutation = useMutation({
    mutationFn: async (data: UpdateProfileInput) => {
      const res = await apiRequest("PUT", "/api/settings/profile", data);
      return res.json();
    },
    onSuccess: () => {
      toast({ title: "Profile updated", description: "Your name has been saved." });
      queryClient.invalidateQueries({ queryKey: ["/api/settings/profile"] });
      queryClient.invalidateQueries({ queryKey: ["/api/auth/user"] });
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2"><User className="h-5 w-5" /> Profile</CardTitle>
        </CardHeader>
        <CardContent className="flex items-center justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2"><User className="h-5 w-5" /> Profile</CardTitle>
        <CardDescription>Update your personal information</CardDescription>
      </CardHeader>
      <CardContent>
        <Form {...form}>
          <form onSubmit={form.handleSubmit((data) => updateMutation.mutate(data))} className="space-y-4">
            <div className="space-y-2">
              <Label className="text-muted-foreground">Email</Label>
              <Input
                value={profile?.email || ""}
                disabled
                data-testid="input-email-display"
              />
              <p className="text-xs text-muted-foreground">Email cannot be changed</p>
            </div>

            <FormField
              control={form.control}
              name="firstName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>First Name</FormLabel>
                  <FormControl>
                    <Input {...field} data-testid="input-first-name" />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="lastName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Last Name</FormLabel>
                  <FormControl>
                    <Input {...field} data-testid="input-last-name" />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <Button type="submit" disabled={updateMutation.isPending} data-testid="button-save-profile">
              {updateMutation.isPending ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : (
                <Check className="h-4 w-4 mr-2" />
              )}
              Save Changes
            </Button>
          </form>
        </Form>
      </CardContent>
    </Card>
  );
}

function PasswordSection() {
  const { toast } = useToast();
  const [showForm, setShowForm] = useState(false);

  const { data: profile, isLoading: profileLoading } = useQuery<ProfileData>({
    queryKey: ["/api/settings/profile"],
  });

  const form = useForm<ChangePasswordInput>({
    resolver: zodResolver(changePasswordSchema),
    defaultValues: {
      currentPassword: "",
      newPassword: "",
    },
  });

  const changeMutation = useMutation({
    mutationFn: async (data: ChangePasswordInput) => {
      const res = await apiRequest("POST", "/api/settings/change-password", data);
      return res.json();
    },
    onSuccess: () => {
      toast({ title: "Password changed", description: "Your password has been updated successfully." });
      form.reset();
      setShowForm(false);
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  if (profileLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2"><Lock className="h-5 w-5" /> Password</CardTitle>
        </CardHeader>
        <CardContent className="flex items-center justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  if (!profile?.hasPassword) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2"><Lock className="h-5 w-5" /> Password</CardTitle>
          <CardDescription>Your account uses an external login method. Password management is not available.</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2"><Lock className="h-5 w-5" /> Password</CardTitle>
        <CardDescription>Change your account password</CardDescription>
      </CardHeader>
      <CardContent>
        {!showForm ? (
          <Button variant="outline" onClick={() => setShowForm(true)} data-testid="button-change-password">
            Change Password
          </Button>
        ) : (
          <Form {...form}>
            <form onSubmit={form.handleSubmit((data) => changeMutation.mutate(data))} className="space-y-4">
              <FormField
                control={form.control}
                name="currentPassword"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Current Password</FormLabel>
                    <FormControl>
                      <Input type="password" {...field} data-testid="input-current-password" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="newPassword"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>New Password</FormLabel>
                    <FormControl>
                      <Input type="password" {...field} data-testid="input-new-password" />
                    </FormControl>
                    <FormDescription>
                      At least 8 characters with uppercase, lowercase, number, and special character
                    </FormDescription>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <div className="flex items-center gap-2">
                <Button type="submit" disabled={changeMutation.isPending} data-testid="button-submit-password">
                  {changeMutation.isPending ? (
                    <Loader2 className="h-4 w-4 animate-spin mr-2" />
                  ) : (
                    <Lock className="h-4 w-4 mr-2" />
                  )}
                  Update Password
                </Button>
                <Button type="button" variant="ghost" onClick={() => { setShowForm(false); form.reset(); }} data-testid="button-cancel-password">
                  Cancel
                </Button>
              </div>
            </form>
          </Form>
        )}
      </CardContent>
    </Card>
  );
}

interface NotificationToggle {
  key: keyof NotificationPrefs;
  label: string;
  description: string;
  visibleForRoles: string[];
}

const notificationToggles: NotificationToggle[] = [
  {
    key: "incorporationUpdates",
    label: "Incorporation Updates",
    description: "Receive emails about your application status changes",
    visibleForRoles: ["founder"],
  },
  {
    key: "orderUpdates",
    label: "Order Updates",
    description: "Get notified when your order status changes",
    visibleForRoles: ["founder"],
  },
  {
    key: "serviceRequestUpdates",
    label: "Service Request Updates",
    description: "Get notified when service requests are updated or assigned",
    visibleForRoles: ["founder", "lawyer", "admin"],
  },
  {
    key: "complianceReminders",
    label: "Compliance Reminders",
    description: "Receive reminders about upcoming compliance deadlines",
    visibleForRoles: ["founder"],
  },
  {
    key: "marketingEmails",
    label: "Marketing & Announcements",
    description: "Receive updates about new features and promotions",
    visibleForRoles: ["founder", "lawyer", "admin"],
  },
];

function NotificationSection({ roles }: { roles: string[] }) {
  const { toast } = useToast();

  const { data: prefs, isLoading } = useQuery<NotificationPrefs>({
    queryKey: ["/api/settings/notifications"],
  });

  const updateMutation = useMutation({
    mutationFn: async (data: NotificationPrefs) => {
      const res = await apiRequest("PUT", "/api/settings/notifications", data);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/settings/notifications"] });
      toast({ title: "Preferences saved", description: "Your notification preferences have been updated." });
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const handleToggle = (key: keyof NotificationPrefs, value: boolean) => {
    if (!prefs) return;
    const updated = { ...prefs, [key]: value };
    updateMutation.mutate(updated);
  };

  const visibleToggles = notificationToggles.filter(
    (toggle) => toggle.visibleForRoles.some((r) => roles.includes(r))
  );

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2"><Bell className="h-5 w-5" /> Notifications</CardTitle>
        </CardHeader>
        <CardContent className="flex items-center justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2"><Bell className="h-5 w-5" /> Notifications</CardTitle>
        <CardDescription>Choose which email notifications you want to receive</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          {visibleToggles.map((toggle) => (
            <div key={toggle.key} className="flex items-center justify-between gap-4">
              <div className="space-y-0.5">
                <Label className="text-sm font-medium" data-testid={`label-${toggle.key}`}>{toggle.label}</Label>
                <p className="text-xs text-muted-foreground">{toggle.description}</p>
              </div>
              <Switch
                checked={prefs?.[toggle.key] ?? true}
                onCheckedChange={(value) => handleToggle(toggle.key, value)}
                disabled={updateMutation.isPending}
                data-testid={`switch-${toggle.key}`}
              />
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

client/src/pages/lawyer/service-requests.content:
import { useQuery } from "@tanstack/react-query";
import { Link } from "wouter";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Loader2, CheckCircle2, Clock, XCircle, ArrowRight, FileText, User } from "lucide-react";

function getStatusBadge(status: string) {
  switch (status) {
    case "completed":
      return <Badge variant="default"><CheckCircle2 className="h-3 w-3 mr-1" /> Completed</Badge>;
    case "in_progress":
      return <Badge variant="secondary"><Clock className="h-3 w-3 mr-1" /> In Progress</Badge>;
    case "assigned":
      return <Badge variant="secondary"><Clock className="h-3 w-3 mr-1" /> Assigned</Badge>;
    case "cancelled":
      return <Badge variant="destructive"><XCircle className="h-3 w-3 mr-1" /> Cancelled</Badge>;
    case "queued":
    default:
      return <Badge variant="outline"><Clock className="h-3 w-3 mr-1" /> Queued</Badge>;
  }
}

function getServiceLabel(serviceType: string): string {
  const labels: Record<string, string> = {
    SCUML: "SCUML Registration",
    TM: "Trademark Registration",
    TIN: "TIN Registration",
  };
  return labels[serviceType] || serviceType;
}

interface ServiceRequestWithFounder {
  id: number;
  founderId: string;
  orderId: number | null;
  serviceType: string;
  status: string;
  assignedLawyerId: string | null;
  companyProfileId: number | null;
  notes: string | null;
  completedAt: string | null;
  createdAt: string;
  founder: {
    email: string | null;
    firstName: string | null;
    lastName: string | null;
  };
}

export default function LawyerServiceRequestsPage() {
  const { data: requests, isLoading } = useQuery<ServiceRequestWithFounder[]>({
    queryKey: ["/api/lawyer/service-requests"],
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const assignedRequests = requests?.filter(r => r.assignedLawyerId && ["assigned", "in_progress"].includes(r.status)) || [];
  const queuedRequests = requests?.filter(r => r.status === "queued") || [];
  const completedRequests = requests?.filter(r => ["completed", "cancelled"].includes(r.status)) || [];

  return (
    <div className="p-6 max-w-4xl mx-auto space-y-6">
      <div>
        <h1 className="text-2xl font-bold" data-testid="text-service-requests-title">Service Requests</h1>
        <p className="text-muted-foreground mt-1">Manage post-incorporation service requests from founders</p>
      </div>

      {assignedRequests.length > 0 && (
        <div className="space-y-3">
          <h2 className="text-lg font-semibold">Your Active Requests</h2>
          {assignedRequests.map(renderRequestCard)}
        </div>
      )}

      {queuedRequests.length > 0 && (
        <div className="space-y-3">
          <h2 className="text-lg font-semibold">Unassigned Queue</h2>
          {queuedRequests.map(renderRequestCard)}
        </div>
      )}

      {completedRequests.length > 0 && (
        <div className="space-y-3">
          <h2 className="text-lg font-semibold text-muted-foreground">Completed / Cancelled</h2>
          {completedRequests.map(renderRequestCard)}
        </div>
      )}

      {!requests?.length && (
        <Card>
          <CardContent className="p-8 text-center">
            <FileText className="h-12 w-12 text-muted-foreground/30 mx-auto mb-4" />
            <p className="text-muted-foreground">No service requests yet.</p>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

function renderRequestCard(request: ServiceRequestWithFounder) {
  const founderName = request.founder.firstName && request.founder.lastName
    ? `${request.founder.firstName} ${request.founder.lastName}`
    : request.founder.email || "Unknown";

  return (
    <Link key={request.id} href={`/lawyer/service-requests/${request.id}`}>
      <Card className="hover-elevate cursor-pointer" data-testid={`card-service-request-${request.id}`}>
        <CardContent className="p-4">
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <div className="flex items-center gap-3 min-w-0">
              <div className="p-2 rounded-md bg-muted flex-shrink-0">
                <FileText className="h-5 w-5" />
              </div>
              <div className="min-w-0">
                <p className="font-medium">{getServiceLabel(request.serviceType)}</p>
                <div className="flex items-center gap-2 mt-0.5 flex-wrap">
                  <span className="text-sm text-muted-foreground flex items-center gap-1">
                    <User className="h-3 w-3" /> {founderName}
                  </span>
                  <span className="text-xs text-muted-foreground">
                    {new Date(request.createdAt).toLocaleDateString("en-NG", { month: "short", day: "numeric" })}
                  </span>
                </div>
                <div className="flex items-center gap-2 mt-1 flex-wrap">
                  {request.companyProfileId ? (
                    <Badge variant="outline" className="text-xs"><CheckCircle2 className="h-3 w-3 mr-1" /> Docs Submitted</Badge>
                  ) : (
                    <Badge variant="outline" className="text-xs"><Clock className="h-3 w-3 mr-1" /> Awaiting Docs</Badge>
                  )}
                </div>
              </div>
            </div>
            <div className="flex items-center gap-3 flex-shrink-0">
              {getStatusBadge(request.status)}
              <ArrowRight className="h-4 w-4 text-muted-foreground" />
            </div>
          </div>
        </CardContent>
      </Card>
    </Link>
  );
}

